local PUI = _G.PhoenixUI if not (PUI and PUI.gateOpen) then return end
-- arSA translations (optional language). There is no Arabic WoW client, so
-- Arabic is chosen in Phoenix settings (Language -> Arabic) and never by Auto.
-- The game's text engine neither joins Arabic letters nor lays out
-- right-to-left, so these strings are stored in normal (logical) order and
-- PUI.Shaper converts them to joined presentation forms in visual order when
-- they are shown; the Language font setting switches Phoenix text to Noto
-- Sans Arabic. .tools/locale_tokens.py checks every format spec, escape and
-- slash command survives. Any string not listed falls back to English.
PUI.Locale:Add("arSA", {
  ["+2 / +3 marks on the timer bar"] = "علامات +2 / +3 على شريط المؤقت",
  ["/gg"] = "/gg",
  ["/gg message"] = "رسالة /gg",
  ["/keys command"] = "أمر /keys",
  ["/pui council <item> asks your group Need, Minor, Transmog or Pass; answers come back with item level. Others need Phoenix with Council on."] = "يسأل /pui council <غرض> مجموعتك: حاجة، تحسين بسيط، تحويل المظهر أو تمرير؛ وتصل الإجابات مع مستوى الغرض. يحتاج الآخرون إلى Phoenix مع تفعيل Council.",
  ["/pui pull [s] (also /pui cd), /pui break [min], /pui rc."] = "/pui pull [ث] (أو /pui cd)، /pui break [د]، /pui rc.",
  ["/pui rl"] = "/pui rl",
  ["/pui simc opens your character as a SimulationCraft profile, ready to copy into SimulationCraft or Raidbots."] = "يفتح /pui simc شخصيتك كملف SimulationCraft جاهز للنسخ إلى SimulationCraft أو Raidbots.",
  ["0 = off. Errors seen in 3 or more sessions become your baseline; when this many errors outside the baseline happen in one session, one chat line says so (once per session)."] = "0 = إيقاف. الأخطاء التي تظهر في 3 جلسات أو أكثر تصبح خط الأساس؛ وعندما يقع هذا العدد من الأخطاء خارج خط الأساس في جلسة واحدة، يظهر سطر واحد في الدردشة (مرة لكل جلسة).",
  ["0 keeps the summary card open until you close it."] = "0 يُبقي بطاقة الملخص مفتوحة حتى تغلقها.",
  ["0 makes the bar background invisible."] = "0 يجعل خلفية الشريط غير مرئية.",
  ["0 poor, 1 common, 2 uncommon, 3 rare, 4 epic, 5 legendary, 6 artifact, 7 heirloom."] = "0 رديء، 1 عادي، 2 غير شائع، 3 نادر، 4 ملحمي، 5 أسطوري، 6 أثري، 7 موروث.",
  ["12.4K instead of 12,400."] = "12.4K بدلًا من 12,400.",
  ["24-hour clock"] = "ساعة 24 ساعة",
  ["24-hour clock block"] = "كتلة ساعة 24 ساعة",
  ["24-hour time instead of AM/PM."] = "وقت بنظام 24 ساعة بدلًا من AM/PM.",
  ["A 1 px theme border around each skinned button."] = "إطار بلون السمة بعرض 1 بكسل حول كل زر مُنسّق.",
  ["A Phoenix button in the inbox that takes only the gold (no items, skips COD) from every mail."] = "زر Phoenix في صندوق البريد يأخذ الذهب فقط (دون الأغراض، ويتخطى الدفع عند الاستلام) من كل رسالة.",
  ["A Phoenix search box: items on the page that do not match fade."] = "مربع بحث Phoenix: الأغراض غير المطابقة في الصفحة تخفت.",
  ["A banner with rising embers when you earn an achievement, time a key or level up. Reduced motion (Glows page) keeps only the banner."] = "لافتة بجمرات متصاعدة عند نيل إنجاز أو إنهاء مفتاح في الوقت أو رفع المستوى. الحركة المخففة (صفحة التوهج) تُبقي اللافتة فقط.",
  ["A bar for spec resources that live in an aura (for example a stacking buff). Set the spell below."] = "شريط لموارد التخصص المخزنة في تأثير (مثل تعزيز متراكم). حدد التعويذة أدناه.",
  ["A bar glows when the game marks the ability as about to happen (the timing comes from the game)."] = "يتوهج الشريط عندما تشير اللعبة إلى أن القدرة على وشك الحدوث (التوقيت من اللعبة).",
  ["A bar that counts down to your next melee swing. Off by default; Forever only. It reads your own swings from the combat log."] = "شريط يعد تنازليًا حتى ضربتك القريبة التالية. مُعطّل افتراضيًا؛ Forever فقط. يقرأ ضرباتك من سجل القتال.",
  ["A block of extra frames for every tank (or healer) in the group, in addition to the normal frames."] = "مجموعة إطارات إضافية لكل مدافع (أو معالج) في المجموعة، بالإضافة إلى الإطارات العادية.",
  ["A bright edge when absorbs run past full health, and when heal absorbs eat more than the health left."] = "حافة ساطعة عندما يتجاوز الامتصاص الصحة الكاملة، وعندما يلتهم امتصاص العلاج أكثر من الصحة المتبقية.",
  ["A bright line where the bar is draining."] = "خط ساطع حيث ينقص الشريط.",
  ["A button in Blizzard's Edit Mode window that opens Phoenix Studio."] = "زر في نافذة وضع التحرير من Blizzard يفتح Phoenix Studio.",
  ["A button on the panel that cancels your oldest application, so a new one fits under the limit of five. In combat it waits until combat ends."] = "زر على اللوحة يلغي أقدم طلب لك كي يتسع طلب جديد ضمن حد الخمسة. أثناء القتال ينتظر حتى انتهائه.",
  ["A button that leaves the vehicle, shown only when you can exit."] = "زر لمغادرة المركبة، يظهر فقط عندما يمكنك الخروج.",
  ["A class icon on each friend row."] = "أيقونة الفئة على كل صف صديق.",
  ["A click on a window's header opens a Phoenix list of meter types instead of cycling through them."] = "النقر على ترويسة النافذة يفتح قائمة Phoenix بأنواع العدّاد بدلًا من التنقل بينها.",
  ["A clickable button beside quests that have a usable item (placed outside combat)."] = "زر قابل للنقر بجانب المهام التي لها غرض قابل للاستخدام (يوضع خارج القتال).",
  ["A cog in the title bar of every skinned window opens its Phoenix options in place."] = "ترس في شريط عنوان كل نافذة مُنسّقة يفتح خيارات Phoenix الخاصة بها في مكانها.",
  ["A coloured dot for each party member targeting this enemy (shared with the party frames' enemy dots)."] = "نقطة ملونة لكل عضو في المجموعة يستهدف هذا العدو (مشتركة مع نقاط الأعداء في إطارات المجموعة).",
  ["A coloured glow around player, target, focus and boss frames when you have threat."] = "توهج ملون حول إطارات اللاعب والهدف والتركيز والزعماء عندما يكون لديك تهديد.",
  ["A countdown bar under the dungeon and battleground ready pop-ups (same countdown as the minimap queue eye)."] = "شريط عد تنازلي تحت نوافذ جاهزية الزنزانة وساحة المعركة (نفس العد التنازلي لعين الطابور على الخريطة المصغرة).",
  ["A countdown bar while you fly. The first flight on a route is timed and remembered."] = "شريط عد تنازلي أثناء الطيران. أول رحلة على كل مسار تُوقَّت وتُحفَظ.",
  ["A dark background behind the tracker."] = "خلفية داكنة خلف المتتبع.",
  ["A faint bar on your row showing your best pull on this boss."] = "شريط باهت على صفك يعرض أفضل سحب لك على هذا الزعيم.",
  ["A gold border around the enemy you are targeting."] = "إطار ذهبي حول العدو الذي تستهدفه.",
  ["A green arrow on loot and rolls with a higher item level than what you wear."] = "سهم أخضر على الغنائم والرميات ذات مستوى غرض أعلى مما ترتديه.",
  ["A grey cross when a cast is stopped before it finishes."] = "علامة × رمادية عندما يتوقف الإلقاء قبل اكتماله.",
  ["A hit on your target this soon after your cast counts as yours."] = "الإصابة على هدفك بعد إلقائك بهذه المدة تُحسب لك.",
  ["A key that hides or shows every meter window. Empty means no key."] = "مفتاح يُخفي أو يُظهر كل نوافذ العدّاد. فارغ يعني بلا مفتاح.",
  ["A key that resets the meter data. Empty means no key."] = "مفتاح يعيد ضبط بيانات العدّاد. فارغ يعني بلا مفتاح.",
  ["A key that switches on your \"While my layer key is active\" overrides (for example bigger nameplates or a different action bar page look). Leave empty for no key."] = "مفتاح يفعّل تجاوزات «أثناء تفعيل مفتاح الطبقة» (مثل لوحات أسماء أكبر أو شكل مختلف لصفحة الشريط). اتركه فارغًا لعدم وجود مفتاح.",
  ["A light Horde or Alliance tint behind Battle.net friends in World of Warcraft."] = "لمسة خفيفة بلون الحشد أو التحالف خلف أصدقاء Battle.net في World of Warcraft.",
  ["A line naming where arena frames, DR and queue status live."] = "سطر يوضح مكان إطارات الساحة وDR وحالة الطابور.",
  ["A popup grid that opens from the bin button, or a bar that is always shown along the minimap or wherever you move it."] = "شبكة منبثقة تُفتح من زر الحاوية، أو شريط ظاهر دائمًا على طول الخريطة المصغرة أو أينما نقلته.",
  ["A progress bar for experience, your watched reputation or honor. Data Bars owns this bar."] = "شريط تقدم للخبرة أو السمعة المتابعة أو الشرف. أشرطة البيانات تملك هذا الشريط.",
  ["A red cross when a cast is interrupted."] = "علامة × حمراء عند مقاطعة الإلقاء.",
  ["A red mark on enchantable slots without an enchant."] = "علامة حمراء على الخانات القابلة للسحر بدون سحر.",
  ["A repeat inside this time is hidden when Hide repeated lines is on."] = "يُخفى التكرار خلال هذه المدة عند تفعيل إخفاء الأسطر المكررة.",
  ["A right click on the header opens a list of fights (current, overall, last saved) instead of cycling."] = "النقر الأيمن على الترويسة يفتح قائمة بالمعارك (الحالية، الإجمالية، آخر محفوظة) بدلًا من التنقل.",
  ["A ring around your mouse cursor, so you never lose it in a busy fight."] = "حلقة حول مؤشر الفأرة كي لا تفقده في معركة مزدحمة.",
  ["A row of small buttons (Say, Party, Instance, Raid, Guild, Officer, Whisper, 1, 2) that open the chat box on that channel."] = "صف من الأزرار الصغيرة (قول، مجموعة، زنزانة، غارة، نقابة، ضابط، همس، 1، 2) تفتح صندوق الدردشة على تلك القناة.",
  ["A search box in the popup that narrows the buttons by name."] = "مربع بحث في النافذة المنبثقة يصفّي الأزرار بالاسم.",
  ["A small badge with the number of new errors this session; click it to open the viewer."] = "شارة صغيرة بعدد الأخطاء الجديدة في هذه الجلسة؛ انقرها لفتح العارض.",
  ["A small clock for the current fight. It is the one shared timer: the Embers title bar and the Mythic+ card read the same clock."] = "ساعة صغيرة للمعركة الحالية. إنها المؤقت المشترك الوحيد: شريط عنوان Embers وبطاقة الأسطوري+ يقرآن الساعة نفسها.",
  ["A small dot in the middle of the ring."] = "نقطة صغيرة في منتصف الحلقة.",
  ["A small frame for each enemy pet (click to target, right-click to focus)."] = "إطار صغير لكل حيوان أليف للعدو (انقر للاستهداف، وانقر بالأيمن للتركيز).",
  ["A small list of the next boss abilities and their times during a boss fight. Move it in Studio."] = "قائمة صغيرة بقدرات الزعيم التالية وأوقاتها أثناء قتال الزعيم. انقلها في Studio.",
  ["A small mark on your focus."] = "علامة صغيرة على تركيزك.",
  ["A small popup the first time a new error happens (repeats are only counted)."] = "نافذة صغيرة عند حدوث خطأ جديد لأول مرة (التكرارات تُعدّ فقط).",
  ["A small read-only Phoenix panel inside Blizzard's conquest frame with your title progress and conquest."] = "لوحة Phoenix صغيرة للقراءة فقط داخل إطار الغزو من Blizzard تعرض تقدم لقبك ونقاط الغزو.",
  ["A soft glow around reminder icons."] = "توهج ناعم حول أيقونات التذكير.",
  ["A soft shadow under Phoenix window text."] = "ظل ناعم تحت نص نوافذ Phoenix.",
  ["A spell shown in the cooldown manager's Essential or Utility rows is hidden on your bars. Off while the cooldown manager hides icons that are on your bars (pick one)."] = "التعويذة الظاهرة في صفوف «الأساسية» أو «المساعدة» في مدير فترات التهدئة تُخفى على أشرطتك. مُعطّل عندما يُخفي مدير فترات التهدئة الأيقونات الموجودة على أشرطتك (اختر واحدًا).",
  ["A starting look for size, spacing and icon side. Every part can still be changed on its own below."] = "مظهر أولي للحجم والتباعد وجهة الأيقونة. يمكن تغيير كل جزء على حدة أدناه.",
