  ["A thin accent border on the friends frame and an accent line under the open tab."] = "إطار رفيع بلون التمييز على إطار الأصدقاء وخط تمييز تحت التبويب المفتوح.",
  ["A thin accent line at the right edge shows where you are while scrolled."] = "خط تمييز رفيع عند الحافة اليمنى يوضح موضعك أثناء التمرير.",
