  ["Accept role checks for me"] = "قبول فحص الأدوار نيابةً عني",
  ["Accepts a dungeon or raid finder role check with the roles you have set. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "يقبل فحص الأدوار في باحث الزنزانات أو الغارات بالأدوار التي حددتها. تدير Blizzard هذه النافذة بشيفرة محمية؛ ومساعدة إضافة هنا قد تسبب نادرًا رسالة «تم حظر إجراء الواجهة». مُفعّل افتراضيًا لأنك اخترت ذلك؛ أوقفه إن رأيت تلك الرسالة.",
  ["Accepts and turns in quests with at most one reward choice. Hold the pause key to read the quest."] = "يقبل المهام ويسلّمها إذا كان فيها خيار مكافأة واحد على الأكثر. اضغط مفتاح الإيقاف مطولًا لقراءة المهمة.",
  ["Accepts group invites from WoW and Battle.net friends. Never while you are queued or in combat."] = "يقبل دعوات المجموعة من أصدقاء WoW وBattle.net. أبدًا أثناء الانتظار في الطابور أو القتال.",
  ["Accepts group invites from friends, Battle.net friends and guild members. While the Friends module is on, its own per-source switches decide instead."] = "يقبل دعوات المجموعة من الأصدقاء وأصدقاء Battle.net وأعضاء النقابة. عند تفعيل وحدة الأصدقاء، تقرر مفاتيحها لكل مصدر بدلًا من ذلك.",
  ["Accepts group invites from guild members. Never while you are queued or in combat."] = "يقبل دعوات المجموعة من أعضاء النقابة. أبدًا أثناء الانتظار في الطابور أو القتال.",
