  ["Action status text"] = "نص حالة الأمر",
  ["Actions can only be dragged off with the pick-up modifier (Shift by default)."] = "لا يمكن سحب الأوامر إلا بمفتاح الالتقاط (Shift افتراضيًا).",
  ["Activity on the row"] = "النشاط على الصف",
