  ["Add on-use trinkets"] = "إضافة الحلي ذات الاستخدام",
  ["Add text slot: one line each, \"tag @ POINT x y size\" (for example health:percent @ TOPRIGHT 0 10 14)."] = "إضافة خانة نص: سطر لكل واحدة، \"tag @ POINT x y size\" (مثلًا health:percent @ TOPRIGHT 0 10 14).",
  ["Add your own character name to reports. Other players' names are never collected."] = "إضافة اسم شخصيتك إلى التقارير. لا تُجمع أسماء اللاعبين الآخرين أبدًا.",
  ["Add, remove and reorder columns. Column IDs: name, spec, damage, healing, kb, deaths, hk, rating, ratingChange, mmrBefore, mmrAfter, honor, plus any column another addon adds."] = "أضف الأعمدة واحذفها وأعد ترتيبها. معرّفات الأعمدة: name، spec، damage، healing، kb، deaths، hk، rating، ratingChange، mmrBefore، mmrAfter، honor، وأي عمود تضيفه إضافة أخرى.",
  ["AddOn list"] = "قائمة الإضافات",
  ["Addon compartment"] = "حجرة الإضافات",
  ["Addon sections in the viewer open collapsed; click a section header to expand it."] = "تُفتح أقسام الإضافات في العارض مطوية؛ انقر ترويسة القسم لتوسيعه.",
  ["Adds ID lines (spell, item, NPC, quest and 23 more kinds) to tooltips. Phoenix is the only place IDs are added."] = "يضيف أسطر المعرّفات (التعويذة، الغرض، NPC، المهمة و23 نوعًا آخر) إلى التلميحات. Phoenix هو المكان الوحيد الذي تُضاف فيه المعرّفات.",
  ["Adds Phoenix's own emoji: :smile: :grin: :laugh: :wink: :sad: :cry: :angry: :cool: :wow: :think: :sleep: :gg: :heart: :fire: :thumbsup: :dead:."] = "يضيف رموز Phoenix التعبيرية: :smile: :grin: :laugh: :wink: :sad: :cry: :angry: :cool: :wow: :think: :sleep: :gg: :heart: :fire: :thumbsup: :dead:.",
  ["Adds a Phoenix UI button above the Escape menu."] = "يضيف زر Phoenix UI فوق قائمة Escape.",
  ["Adds a Train all button to the class trainer."] = "يضيف زر «تعلّم الكل» إلى مدرب الفئة.",
  ["Adds a glow around the frame while the class icon shows an aura."] = "يضيف توهجًا حول الإطار بينما تعرض أيقونة الفئة تأثيرًا.",
  ["Adds channelled spells to the strip."] = "يضيف التعاويذ الموجّهة إلى الشريط.",
  ["Adds each row's share of the total when the game shows the numbers."] = "يضيف حصة كل صف من الإجمالي عندما تعرض اللعبة الأرقام.",
  ["Adds gear from your bags as commented lines, so Raidbots Top Gear can compare it."] = "يضيف العتاد من حقائبك كأسطر تعليق، ليتمكن Raidbots Top Gear من مقارنته.",
  ["Adds guild name and rank to player tooltips."] = "يضيف اسم النقابة والرتبة إلى تلميحات اللاعبين.",
  ["Adds kills, wipes and your best time to the tooltip of a boss you have stats for."] = "يضيف القتلات والإبادات وأفضل وقت لك إلى تلميح الزعيم الذي لديك إحصاءات عنه.",
  ["Adds roles in fixed order, class-coloured counts, age, leader score and decline memory to the group tooltip."] = "يضيف إلى تلميح المجموعة الأدوار بترتيب ثابت، وأعدادًا ملونة حسب الفئة، والعمر، وتقييم القائد، وذاكرة الرفض.",
  ["Adds the Phoenix score or item-level difference to item tooltips."] = "يضيف تقييم Phoenix أو فرق مستوى الغرض إلى تلميحات الأغراض.",
  ["Adds the enemy forces of the enemies you are fighting to the forces line."] = "يضيف قوات الأعداء الذين تقاتلهم إلى سطر القوات.",
  ["Adds the highest key the player finished this season next to the score."] = "يضيف أعلى مفتاح أنهاه اللاعب هذا الموسم بجانب التقييم.",
  ["Adds the leader's best timed key level in that dungeon next to the score."] = "يضيف أفضل مستوى مفتاح أنهاه القائد في الوقت في تلك الزنزانة بجانب التقييم.",
  ["Adds the per-second figure to saved segments."] = "يضيف قيمة كل ثانية إلى المقاطع المحفوظة.",
  ["Adds the player's Mythic+ score, coloured by your M+ score colour setting."] = "يضيف تقييم الأسطوري+ للاعب، ملونًا حسب إعداد لون تقييم M+.",
  ["Adds the raid size to the difficulty, such as 25H."] = "يضيف حجم الغارة إلى الصعوبة، مثل 25H.",
  ["Adds your equipped trinkets that have a use effect to the item bars."] = "يضيف الحلي المرتداة ذات تأثير الاستخدام إلى أشرطة الأغراض.",
  ["Advanced: macro conditions that show or hide bar 1, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 1، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 10, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 10، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 2, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 2، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 3, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 3، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 4, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 4، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 5, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 5، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 6, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 6، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 7, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 7، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 8, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 8، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Advanced: macro conditions that show or hide bar 9, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "متقدم: شروط ماكرو تُظهر أو تُخفي الشريط 9، مثل [combat] show; hide. عند تحديدها تحل محل اختيار مكان الإظهار.",
  ["Adventure Guide"] = "دليل المغامرات",
  ["After a boss, sends the top line through Phoenix announcements (where it goes is set on the Announcements page)."] = "بعد الزعيم، يرسل السطر الأول عبر إعلانات Phoenix (تُحدد الوجهة في صفحة الإعلانات).",
  ["After a ready check, prints who was not ready or did not answer."] = "بعد فحص الجاهزية، يطبع من لم يكن جاهزًا أو لم يُجب.",
  ["After a restore, make the Phoenix Edit Mode layout the active one."] = "بعد الاستعادة، اجعل تخطيط وضع التحرير من Phoenix هو النشط.",
  ["After a run"] = "بعد الجولة",
  ["After a talent or specialization change, lists tracked cooldowns that are on none of your action bars."] = "بعد تغيير المواهب أو التخصص، يسرد فترات التهدئة المتابعة غير الموجودة على أي شريط أوامر.",
  ["After an enemy is seen dispelling, shows their dispel with its cooldown. Only dispels the game reports plainly are seen."] = "بعد رؤية عدو يبدد، يعرض تبديده مع فترة تهدئته. لا تُرى إلا التبديدات التي تبلغ عنها اللعبة صراحةً.",
  ["After an enemy's cast is interrupted, the plate shows \"Interrupted by <name>\" for a moment."] = "بعد مقاطعة إلقاء العدو، تعرض اللوحة «قاطعه <الاسم>» لحظة.",
  ["After-match card"] = "بطاقة ما بعد المباراة",
  ["Aggro border"] = "إطار التهديد",
  ["Alert again after (s)"] = "التنبيه مجددًا بعد (ث)",
  ["Alert sound"] = "صوت التنبيه",
  ["Alert toasts"] = "إشعارات التنبيه",
  ["Alerts and toasts"] = "التنبيهات والإشعارات",
  ["All tracked quests, only those in progress, or only those ready to turn in."] = "كل المهام المتابعة، أو الجارية فقط، أو الجاهزة للتسليم فقط.",
  ["Alphabetical, or the order you drag them into (Shift-click the bin button to edit)."] = "أبجديًا، أو بالترتيب الذي تسحبها إليه (Shift مع النقر على زر الحاوية للتحرير).",
  ["Also keeps errors from other addons and Blizzard's code in the viewer, on this PC only. They never join Phoenix's reports unless you allow it below."] = "يحتفظ أيضًا بأخطاء الإضافات الأخرى وشيفرة Blizzard في العارض، على هذا الحاسوب فقط. لا تنضم إلى تقارير Phoenix أبدًا ما لم تسمح بذلك أدناه.",
  ["Also narrow Blizzard's search: minimum rating"] = "تضييق بحث Blizzard أيضًا: أدنى تقييم",
  ["Also narrow Blizzard's search: needs my role"] = "تضييق بحث Blizzard أيضًا: يحتاج دوري",
  ["Also prints the rating change in your chat window after each rated match."] = "يطبع أيضًا تغير التقييم في نافذة الدردشة بعد كل مباراة مصنفة.",
  ["Also shows a dot for each boss targeting this member."] = "يعرض أيضًا نقطة لكل زعيم يستهدف هذا العضو.",
  ["Also shows the addons listed in Blizzard's addon compartment as buttons in the bin."] = "يعرض أيضًا الإضافات المدرجة في حجرة إضافات Blizzard كأزرار في الحاوية.",
  ["Alt+click Phoenix UI in the minimap addon menu to show or clear the Cast History test strip."] = "Alt+نقر على Phoenix UI في قائمة إضافات الخريطة المصغرة لإظهار شريط اختبار Cast History أو مسحه.",
  ["Alt+click in the addon menu"] = "Alt+نقر في قائمة الإضافات",
  ["Alternate power bar"] = "شريط الطاقة البديلة",
  ["Always on the minimap"] = "دائمًا على الخريطة المصغرة",
  ["Always show me"] = "إظهاري دائمًا",
  ["An accent dot on communities with unread messages."] = "نقطة تمييز على المجتمعات التي فيها رسائل غير مقروءة.",
  ["An accent frame on transmog slots with an unsaved change."] = "إطار تمييز على خانات تحويل المظهر التي فيها تغيير غير محفوظ.",
  ["An accent glow on Great Vault slots you have unlocked."] = "توهج تمييز على خانات الخزنة العظمى التي فتحتها.",
  ["An accent line under the open tab."] = "خط تمييز تحت التبويب المفتوح.",
  ["An accent ring on chosen talents, a dim ring on talents you can still pick."] = "حلقة تمييز على المواهب المختارة، وحلقة باهتة على المواهب التي لا يزال بإمكانك اختيارها.",
  ["An essential or utility cooldown that is on one of your shown action bars is left out of these rows, so it appears once."] = "فترة التهدئة الأساسية أو المساعدة الموجودة على أحد أشرطة الأوامر الظاهرة تُستبعد من هذه الصفوف، فتظهر مرة واحدة.",
