  ["Arena: sort"] = "الساحة: الترتيب",
  ["Arrows either side of your target's plate."] = "أسهم على جانبي لوحة هدفك.",
  ["As a tank, plates another tank in your group is holding get their own colour instead of the danger colour."] = "كمدافع، اللوحات التي يمسكها مدافع آخر في مجموعتك تأخذ لونها الخاص بدلًا من لون الخطر.",
  ["Ascent"] = "Ascent",
  ["Asks the game to show only DR categories your own spells can cause (needs DR tracking on). Your old value comes back when off."] = "يطلب من اللعبة عرض فئات DR التي تسببها تعاويذك فقط (يتطلب تتبع DR). تعود قيمتك السابقة عند الإيقاف.",
  ["Asks whether to leave the group when a Dungeon Finder run is complete. Never leaves on its own."] = "يسأل عن مغادرة المجموعة عند اكتمال جولة باحث الزنزانات. لا يغادر من تلقاء نفسه أبدًا.",
