  ["Automations: repair, junk, release, invites, cinematics, quick loot and more. Each one off until you turn it on."] = "الأتمتة: الإصلاح والخردة وتحرير الروح والدعوات والمشاهد السينمائية والنهب السريع وغيرها. كل منها مُعطّل حتى تفعّله.",
  ["Background"] = "الخلفية",
