  ["Bags and bank in one window: categories with your own rules, junk, keystone shelf, undo sort, alts and gold history."] = "الحقائب والمصرف في نافذة واحدة: فئات بقواعدك، والخردة، ورف حجر المفتاح، والتراجع عن الفرز، والشخصيات البديلة، وسجل الذهب.",
