  ["Bars fill from the right."] = "تمتلئ الأشرطة من اليمين.",
  ["Bars for upcoming boss abilities, read from the game's own encounter timeline. With BigWigs or DBM loaded, you choose who shows them."] = "أشرطة لقدرات الزعيم القادمة، مقروءة من الخط الزمني للمواجهة في اللعبة. عند تحميل BigWigs أو DBM تختار من يعرضها.",
  ["Bars grow"] = "نمو الأشرطة",
  ["Bars in Blizzard's meter use your class colours from the Colours page."] = "تستخدم الأشرطة في عدّاد Blizzard ألوان الفئات من صفحة الألوان.",
  ["Bars past this number wait until a slot frees up (soonest first)."] = "الأشرطة بعد هذا العدد تنتظر حتى تتوفر خانة (الأقرب أولًا).",
  ["Bars use the game's colour for how dangerous each ability is. Off: every bar uses the normal colour."] = "تستخدم الأشرطة لون اللعبة لمدى خطورة كل قدرة. عند الإيقاف: كل الأشرطة باللون العادي.",
