  ["Colour wash over the settings window glass. Alpha sets how strong it is (0 = none). Glass opacity is in Theme & Media."] = "طبقة لون فوق زجاج نافذة الإعدادات. ألفا تحدد قوتها (0 = لا شيء). عتامة الزجاج في السمة والوسائط.",
