  ["Colours a group's name: new since your last search, declined you, cancelled or delisted. Each colour is its own setting."] = "يلوّن اسم المجموعة: جديدة منذ بحثك الأخير، رفضتك، ملغاة أو مسحوبة. لكل لون إعداده الخاص.",
  ["Colours each slot's border by item quality, using the game's quality colours (your colour overrides apply)."] = "يلوّن إطار كل خانة حسب جودة الغرض بألوان اللعبة (تُطبق تجاوزات ألوانك).",
