  ["Comma-separated blocks in order; empty hides the bar. Use currency:ID for one currency and ldb:Name for a LibDataBroker feed. Blocks: bags, clock, coords, currencies, currency, durability, fps, friends, gold, guild, hearth, honor, ilvl, latency, ldb, location, mail, mplus, prof1, prof2, rep, session, spec, vault, volume, xp."] = "كتل مفصولة بفواصل بالترتيب؛ الفراغ يخفي الشريط. استخدم currency:ID لعملة واحدة وldb:Name لمصدر LibDataBroker. الكتل: bags, clock, coords, currencies, currency, durability, fps, friends, gold, guild, hearth, honor, ilvl, latency, ldb, location, mail, mplus, prof1, prof2, rep, session, spec, vault, volume, xp.",
  ["Comma-separated percentages (1-99) where thin lines are drawn on the power bar, e.g. 30, 60."] = "نسب مئوية مفصولة بفواصل (1-99) تُرسم عندها خطوط رفيعة على شريط الطاقة، مثل 30, 60.",
  ["Comma-separated whole words (case does not matter)."] = "كلمات كاملة مفصولة بفواصل (حالة الأحرف لا تهم).",
  ["Comma-separated words. A line containing one is highlighted, plays a sound and flashes the game icon."] = "كلمات مفصولة بفواصل. السطر الذي يحتوي إحداها يُميَّز ويشغّل صوتًا ويومض أيقونة اللعبة.",
  ["Command palette: search settings, panels, macros, mounts, profiles and commands from one box."] = "لوحة الأوامر: ابحث في الإعدادات واللوحات والماكرو والمطايا والملفات الشخصية والأوامر من مربع واحد.",
