  ["Dispel icon size."] = "حجم أيقونة التبديد.",
  ["Dispel tint strength"] = "قوة صبغة التبديد",
  ["Dispel tracker"] = "متتبع التبديد",
  ["Distance labels"] = "تسميات المسافة",
  ["Do not share repeatable quests"] = "عدم مشاركة المهام القابلة للتكرار",
  ["Dock several meter windows together under one Studio mover (Embers dock), or leave them free."] = "إرساء عدة نوافذ عدّاد معًا تحت محرّك Studio واحد (إرساء Embers)، أو تركها حرة.",
  ["Docked above the group finder: your roles at a glance, with locks on roles your class cannot play."] = "مُرسى فوق باحث المجموعات: أدوارك بنظرة واحدة، مع أقفال على الأدوار التي لا تستطيع فئتك لعبها.",
  ["Docked inside the M+ block or as its own widget (also shown in raid boss fights)."] = "مُرسى داخل كتلة M+ أو كأداة مستقلة (يظهر أيضًا في معارك زعماء الغارات).",
  ["Docked panel with Phoenix's sorted list of the groups your filter keeps and the why-hidden line."] = "لوحة مُرساة بقائمة Phoenix المرتبة للمجموعات التي يُبقيها مرشحك وسطر «سبب الإخفاء».",
  ["Docked window gap"] = "فجوة النوافذ المُرساة",
  ["Docks the Mythic+ block at the top of the Phoenix quest tracker, or shows it as its own movable window. When the Phoenix tracker is off it always uses its own window."] = "يُرسي كتلة الأسطوري+ أعلى متتبع مهام Phoenix، أو يعرضها كنافذة مستقلة قابلة للنقل. عند إيقاف متتبع Phoenix تستخدم دائمًا نافذتها الخاصة.",
  ["Docks the bar on the minimap edge the bar grows along, or lets you place it with the Studio mover."] = "يُرسي الشريط على حافة الخريطة المصغرة التي ينمو على طولها، أو يتيح لك وضعه بمحرّك Studio.",
  ["Does not repeat the exact same announcement within 5 seconds."] = "لا يكرر الإعلان نفسه خلال 5 ثوانٍ.",
  ["Double-click a group (in Blizzard's list or Phoenix's) to open its sign-up. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "انقر مرتين على مجموعة (في قائمة Blizzard أو Phoenix) لفتح التسجيل فيها. تدير Blizzard هذه النافذة بشيفرة محمية؛ ومساعدة إضافة هنا قد تسبب نادرًا رسالة «تم حظر إجراء الواجهة». مُفعّل افتراضيًا لأنك اخترت ذلك؛ أوقفه إن رأيت تلك الرسالة.",
  ["Double-click a group to sign up"] = "انقر مرتين على مجموعة للتسجيل",
  ["Drag Blizzard windows (character, map, bags, talents and about 50 more) by their title. Ctrl + mouse wheel scales, Shift + right-click resets."] = "اسحب نوافذ Blizzard (الشخصية، الخريطة، الحقائب، المواهب ونحو 50 غيرها) من عنوانها. Ctrl + عجلة الفأرة يغيّر المقياس، وShift + النقر الأيمن يعيد الضبط.",
  ["Drag a scoreboard header onto another to change the column order."] = "اسحب ترويسة لوحة النتائج إلى أخرى لتغيير ترتيب الأعمدة.",
  ["Drag scoreboard headers"] = "سحب ترويسات لوحة النتائج",
  ["Drag the whole selection"] = "سحب التحديد كله",
  ["Dragged elements snap to the Studio grid."] = "العناصر المسحوبة تلتصق بشبكة Studio.",
  ["Draw the pixel grid while Studio is open."] = "رسم شبكة البكسل أثناء فتح Studio.",
  ["Draw the screen's centre lines while Studio is open."] = "رسم خطوط منتصف الشاشة أثناء فتح Studio.",
  ["Draws a line from each attached element to the element it is attached to while Studio is open."] = "يرسم خطًا من كل عنصر مرتبط إلى العنصر المرتبط به أثناء فتح Studio.",
  ["Draws a thin line at the execute percent."] = "يرسم خطًا رفيعًا عند نسبة الإجهاز.",
  ["Draws each button on a Phoenix tile with an icon mask; turn off to keep each addon's own look."] = "يرسم كل زر على مربع Phoenix بقناع أيقونة؛ أوقفه للإبقاء على مظهر كل إضافة.",
  ["Draws the bright moving edge on the cooldown swipe."] = "يرسم الحافة المتحركة الساطعة على مسح فترة التهدئة.",
  ["Draws the frame of buttons that hold no action."] = "يرسم إطار الأزرار التي لا تحمل أمرًا.",
  ["Draws the pull, break and key countdown that Raid Tools runs (yours or anyone's in the group)."] = "يرسم العد التنازلي للسحب والاستراحة والمفتاح الذي يشغّله Raid Tools (لك أو لأي شخص في المجموعة).",
  ["Dressing room"] = "غرفة القياس",
  ["Dropdowns"] = "القوائم المنسدلة",
  ["Druid colour"] = "لون الدرويد",
  ["Dungeon queue-pop time"] = "وقت ظهور دعوة الزنزانة",
  ["Dungeon ready pop-up"] = "نافذة جاهزية الزنزانة",
