  ["EU, US, KR, TW or CN for Battle.net friends."] = "EU أو US أو KR أو TW أو CN لأصدقاء Battle.net.",
  ["Each bracket's rating, season best and this week's record."] = "تقييم كل فئة، وأفضل الموسم، وسجل هذا الأسبوع.",
  ["Each specialization can keep its own block list for every bar (save one with /pui dbspec save). Specs without a saved set use the normal lists."] = "يمكن لكل تخصص الاحتفاظ بقائمة حظر خاصة لكل شريط (احفظها بـ /pui dbspec save). التخصصات بلا مجموعة محفوظة تستخدم القوائم العادية.",
  ["Each specialization can use its own profile. When you change spec, Phoenix switches to that profile (after combat). Content profiles for raid, arena or Mythic+ still apply on top."] = "يمكن لكل تخصص استخدام ملف شخصي خاص. عند تغيير التخصص ينتقل Phoenix إلى ذلك الملف (بعد القتال). ملفات المحتوى للغارة أو الساحة أو الأسطوري+ تبقى مطبقة فوقه.",
  ["Each time you save in Edit Mode, Phoenix keeps a copy of the active layout in this profile; /pui editmode restore puts it back as a layout named Phoenix."] = "في كل مرة تحفظ في وضع التحرير يحتفظ Phoenix بنسخة من التخطيط النشط في هذا الملف؛ /pui editmode restore يعيده كتخطيط باسم Phoenix.",
