  ["Empty uses \"+%s\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "الفراغ يستخدم \"+%s\". الرموز: %a الكمية، %s التعويذة أو الغرض، %c العدد، %e الحدث، %t اللاحقة (ساحق، خاطف).",
