  ["Fades frames of members out of your range."] = "يخفت إطارات الأعضاء خارج مداك.",
  ["Fades out Blizzard's addon compartment. It comes back when you turn this off or the module off."] = "يخفي حجرة إضافات Blizzard. تعود عند إيقاف هذا الإعداد أو الوحدة.",
  ["Fades out Blizzard's blizzard instance difficulty badge. It comes back when you turn this off or the module off."] = "يخفي شارة صعوبة الزنزانة من Blizzard. تعود عند إيقاف هذا الإعداد أو الوحدة.",
  ["Fades out Blizzard's calendar button. It comes back when you turn this off or the module off."] = "يخفي زر التقويم من Blizzard. يعود عند إيقاف هذا الإعداد أو الوحدة.",
  ["Fades out Blizzard's crafting order icon. It comes back when you turn this off or the module off."] = "يخفي أيقونة طلبات الصنع من Blizzard. تعود عند إيقاف هذا الإعداد أو الوحدة.",
  ["Fades out Blizzard's expansion summary button. It comes back when you turn this off or the module off."] = "يخفي زر ملخص التوسعة من Blizzard. يعود عند إيقاف هذا الإعداد أو الوحدة.",
  ["Fades out Blizzard's mail icon. It comes back when you turn this off or the module off."] = "يخفي أيقونة البريد من Blizzard. تعود عند إيقاف هذا الإعداد أو الوحدة.",
  ["Fades out Blizzard's minimap border, zone bar and compass ring; Phoenix shows the zone itself."] = "يخفي إطار الخريطة المصغرة من Blizzard وشريط المنطقة وحلقة البوصلة؛ ويعرض Phoenix المنطقة بنفسه.",
  ["Fades out Blizzard's tracking button. It comes back when you turn this off or the module off."] = "يخفي زر التتبع من Blizzard. يعود عند إيقاف هذا الإعداد أو الوحدة.",
  ["Fades out Blizzard's zoom buttons. It comes back when you turn this off or the module off."] = "يخفي أزرار التكبير من Blizzard. تعود عند إيقاف هذا الإعداد أو الوحدة.",
  ["Fades target, focus and boss frames that are out of range (when the game can tell)."] = "يخفت إطارات الهدف والتركيز والزعماء خارج المدى (عندما تستطيع اللعبة التحديد).",
  ["Fades the Blizzard objective tracker while a key runs."] = "يخفت متتبع الأهداف من Blizzard أثناء المفتاح.",
  ["Fights in history"] = "المعارك في السجل",
