  ["Hides Sated, Exhaustion, Forbearance and similar lockouts from the debuff icons."] = "يخفي الشبع والإنهاك والتحمل وما شابهها من تأثيرات الإقفال من أيقونات التأثيرات الضارة.",
  ["Hides a buff here when the Cooldown Manager's tracked buff bars already show it, so nothing appears twice."] = "يخفي التعزيز هنا عندما تعرضه أشرطة التعزيزات المتابعة في مدير فترات التهدئة، فلا يظهر شيء مرتين.",
