  ["Hides the big boss-loot and level-up banners."] = "يخفي لافتات غنائم الزعماء ورفع المستوى الكبيرة.",
  ["Hides the default party and raid frames while Phoenix group frames are on."] = "يخفي إطارات المجموعة والغارة الافتراضية أثناء تفعيل إطارات مجموعة Phoenix.",
  ["Hides the default pet bar while the Phoenix one is on."] = "يخفي شريط الحيوان الأليف الافتراضي أثناء تفعيل شريط Phoenix.",
  ["Hides the default player cast bar while the Phoenix cast bar is shown."] = "يخفي شريط إلقاء اللاعب الافتراضي أثناء ظهور شريط إلقاء Phoenix.",
  ["Hides the default stance bar while the Phoenix one is on."] = "يخفي شريط الوضعيات الافتراضي أثناء تفعيل شريط Phoenix.",
  ["Hides the enemy's name while it casts so the cast bar is easier to read."] = "يخفي اسم العدو أثناء إلقائه لتسهل قراءة شريط الإلقاء.",
  ["Hides the expression lines; the list, count and sort stay. Sorting and filters are shared with the full view."] = "يخفي أسطر التعبير؛ وتبقى القائمة والعدّاد والترتيب. الترتيب والمرشحات مشتركة مع العرض الكامل.",
  ["Hides the game's arena frames while Phoenix shows its own (never moved or changed; shown again when this is off)."] = "يخفي إطارات الساحة في اللعبة بينما يعرض Phoenix إطاراته (لا تُنقل ولا تُغيَّر أبدًا؛ تظهر مجددًا عند الإيقاف).",
  ["Hides the gold ring and dark disc minimap buttons draw; given back when skinning is off."] = "يخفي الحلقة الذهبية والقرص الداكن اللذين ترسمهما أزرار الخريطة المصغرة؛ يعودان عند إيقاف التنسيق.",
