  ["Hovering a row opens the spell breakdown beside the window, on the side with more room."] = "المرور فوق صف يفتح تفصيل التعاويذ بجانب النافذة، في الجهة ذات المساحة الأكبر.",
  ["How Phoenix keeps the game's plate out of sight under its own. It always comes back when Phoenix lets the plate go."] = "كيف يُبقي Phoenix لوحة اللعبة مخفية تحت لوحته. تعود دائمًا عندما يتركها Phoenix.",
  ["How a button glows when the game highlights the spell (a proc)."] = "كيف يتوهج الزر عندما تميّز اللعبة التعويذة (تفعيل).",
  ["How a button shows that its target is out of range."] = "كيف يُظهر الزر أن هدفه خارج المدى.",
  ["How a dispellable debuff is shown on the frame."] = "كيف يُعرض التأثير الضار القابل للتبديد على الإطار.",
  ["How amounts are written. Numbers the game hides in combat always use the game's own short format."] = "كيف تُكتب الكميات. الأرقام التي تخفيها اللعبة أثناء القتال تستخدم دائمًا تنسيق اللعبة المختصر.",
  ["How class icons on friend rows look."] = "شكل أيقونات الفئات على صفوف الأصدقاء.",
  ["How close (in UI pixels) an edge must come before it snaps."] = "مدى قرب الحافة (ببكسلات الواجهة) قبل أن تلتصق.",
  ["How dark the cooldown swipe is."] = "مدى قتامة مسح فترة التهدئة.",
  ["How dark the screen gets behind the movers."] = "مدى إظلام الشاشة خلف المحرّكات.",
  ["How each ID line is labelled."] = "كيف يُسمّى كل سطر معرّف.",
  ["How enemy forces are written."] = "كيف تُكتب قوات الأعداء.",
  ["How faded an out-of-range enemy is."] = "مدى خفوت العدو خارج المدى.",
  ["How faded app-only friends are on Blizzard's list while hidden."] = "مدى خفوت أصدقاء التطبيق فقط في قائمة Blizzard أثناء إخفائهم.",
  ["How faded the frame of an enemy who left is."] = "مدى خفوت إطار العدو الذي غادر.",
  ["How far away plates appear; 0 keeps the game's value."] = "المسافة التي تظهر عندها اللوحات؛ 0 يُبقي قيمة اللعبة.",
  ["How far lines travel."] = "مدى انتقال الأسطر.",
  ["How fast pulsing and flashing glows animate."] = "سرعة حركة التوهج النابض والوامض.",
  ["How gold is written in the footer."] = "كيف يُكتب الذهب في التذييل.",
  ["How icons are ordered."] = "كيف تُرتب الأيقونات.",
  ["How large numbers look everywhere in Phoenix (meters, data bars, unit text, combat text)."] = "شكل الأرقام الكبيرة في كل مكان في Phoenix (العدّادات، أشرطة البيانات، نص الوحدات، نص القتال).",
  ["How lines move."] = "كيف تتحرك الأسطر.",
  ["How long Spark waits to merge repeated hits."] = "مدة انتظار Spark لدمج الإصابات المتكررة.",
  ["How long a dungeon or raid finder invite stays open, used for the queue-pop countdown everywhere (minimap queue eye, queue popup). Battleground invites use the game's own expiry."] = "مدة بقاء دعوة باحث الزنزانات أو الغارات مفتوحة، وتُستخدم لعدّ الطابور التنازلي في كل مكان (عين الطابور على الخريطة المصغرة، نافذة الطابور). دعوات ساحات المعارك تستخدم مهلة اللعبة.",
  ["How long a line stays."] = "مدة بقاء السطر.",
  ["How long an icon takes to move one place."] = "المدة التي تستغرقها الأيقونة للتحرك خانة واحدة.",
  ["How long the bar stays after a cast ends, in the interrupted or finished colour; 0 hides it at once."] = "مدة بقاء الشريط بعد انتهاء الإلقاء بلون المقاطعة أو الانتهاء؛ 0 يخفيه فورًا.",
  ["How long the final time stays on screen after a fight."] = "مدة بقاء الوقت النهائي على الشاشة بعد المعركة.",
  ["How long the flash and tag stay."] = "مدة بقاء الوميض والوسم.",
  ["How long the line stays (seconds)."] = "مدة بقاء السطر (ثوانٍ).",
  ["How long the notice stays."] = "مدة بقاء الإشعار.",
  ["How long the question stays on screen before it closes by itself."] = "مدة بقاء السؤال على الشاشة قبل أن يُغلق من تلقاء نفسه.",
  ["How long the ready pop-up ignores clicks."] = "المدة التي تتجاهل فيها نافذة الجاهزية النقرات.",
  ["How many bosses the stats window lists (most recent first)."] = "عدد الزعماء في نافذة الإحصاءات (الأحدث أولًا).",
  ["How many buttons bar 1 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 1 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 10 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 10 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 2 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 2 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 3 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 3 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 4 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 4 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 5 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 5 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 6 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 6 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 7 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 7 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 8 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 8 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons bar 9 shows (an action page holds 12)."] = "عدد الأزرار التي يعرضها الشريط 9 (صفحة الأوامر تتسع لـ 12).",
  ["How many buttons the bin holds."] = "عدد الأزرار التي تتسع لها الحاوية.",
  ["How many casts each strip shows."] = "عدد الإلقاءات التي يعرضها كل شريط.",
  ["How many events the death recap lists before a death."] = "عدد الأحداث التي يسردها ملخص الموت قبل الموت.",
  ["How many finished fights the Pulse page lists with their times."] = "عدد المعارك المنتهية التي تسردها صفحة Pulse مع أوقاتها.",
  ["How many finished fights to keep across reloads (pinned ones are always kept)."] = "عدد المعارك المنتهية المحفوظة عبر إعادة التحميل (المثبتة تُحفظ دائمًا).",
  ["How many fit in one row before wrapping (overflow goes to the next row)."] = "العدد الذي يتسع في صف واحد قبل الالتفاف (الفائض يذهب إلى الصف التالي).",
  ["How many frames before a new column (or row) starts. 5 keeps one group per column."] = "عدد الإطارات قبل بدء عمود (أو صف) جديد. 5 يُبقي مجموعة واحدة لكل عمود.",
  ["How many icons fit on one row before a new row starts."] = "عدد الأيقونات التي تتسع في صف قبل بدء صف جديد.",
  ["How many lines history keeps before the oldest are dropped."] = "عدد الأسطر التي يحفظها السجل قبل حذف الأقدم.",
  ["How many matching groups the panel lists."] = "عدد المجموعات المطابقة التي تسردها اللوحة.",
  ["How many meter windows to show (up to 4). Each one has its own meter type and fight; move them in Studio. Different window sets per raid, Mythic+ or arena come from your content profiles."] = "عدد نوافذ العدّاد المعروضة (حتى 4). لكل منها نوع عدّاد ومعركة؛ انقلها في Studio. مجموعات النوافذ المختلفة للغارة أو الأسطوري+ أو الساحة تأتي من ملفات المحتوى.",
  ["How many names a chat report lists."] = "عدد الأسماء التي يسردها تقرير الدردشة.",
  ["How many pulls per boss the history (and the wipe trend) keeps."] = "عدد السحبات لكل زعيم التي يحفظها السجل (واتجاه الإبادات).",
  ["How many rated results are kept (Arena's card reads them too)."] = "عدد النتائج المصنفة المحفوظة (تقرؤها بطاقة الساحة أيضًا).",
  ["How many rated results the history window lists (/pui pvphistory)."] = "عدد النتائج المصنفة التي تسردها نافذة السجل (/pui pvphistory).",
  ["How many results the palette lists."] = "عدد النتائج التي تسردها اللوحة.",
  ["How many sample enemies the test mode shows."] = "عدد الأعداء التجريبيين في وضع الاختبار.",
  ["How many spells the breakdown lists."] = "عدد التعاويذ التي يسردها التفصيل.",
  ["How many upcoming abilities the list shows."] = "عدد القدرات القادمة التي تعرضها القائمة.",
  ["How much a button darkens while on cooldown."] = "مدى إعتام الزر أثناء فترة التهدئة.",
  ["How much bigger critical hits are."] = "مدى تكبير الضربات الحرجة.",
  ["How numbered channels are written in front of a line."] = "كيف تُكتب القنوات المرقمة أمام السطر.",
  ["How often out-of-range units are re-checked (seconds). Lower reacts faster and costs a little more."] = "عدد مرات إعادة فحص الوحدات خارج المدى (ثوانٍ). الأقل يستجيب أسرع ويكلف قليلًا أكثر.",
  ["How often windows redraw in combat. 0.5 seconds is the fastest; slower saves a little CPU."] = "عدد مرات إعادة رسم النوافذ أثناء القتال. 0.5 ثانية هي الأسرع؛ والأبطأ يوفر قليلًا من المعالج.",
  ["How quests ready to turn in look."] = "شكل المهام الجاهزة للتسليم.",
  ["How solid the row bars are."] = "مدى صلابة أشرطة الصفوف.",
  ["How solid the tooltip background is."] = "مدى صلابة خلفية التلميح.",
  ["How strong the border is (0 hides it, the tab line stays)."] = "قوة الإطار (0 يخفيه، ويبقى خط التبويب).",
  ["How strong the hover highlight is."] = "قوة تمييز المرور.",
  ["How strongly the health bar is tinted."] = "مدى صبغ شريط الصحة.",
  ["How the bag bar shows. Move it in Studio (Edit Mode owns its position)."] = "كيف يظهر شريط الحقائب. انقله في Studio (وضع التحرير يملك موضعه).",
  ["How the fight time is written."] = "كيف يُكتب وقت المعركة.",
  ["How the gold block shows money."] = "كيف تعرض كتلة الذهب المال.",
  ["How the micro menu shows. Move it in Studio (Edit Mode owns its position)."] = "كيف تظهر القائمة المصغرة. انقلها في Studio (وضع التحرير يملك موضعها).",
  ["How the newest icon glows."] = "كيف تتوهج أحدث أيقونة.",
  ["How the popup bin opens."] = "كيف تُفتح الحاوية المنبثقة.",
  ["How the power bar is coloured."] = "كيف يُلوَّن شريط الطاقة.",
  ["How the time left is written."] = "كيف يُكتب الوقت المتبقي.",
  ["How the zone name is coloured."] = "كيف يُلوَّن اسم المنطقة.",
  ["How visible a filtered row stays (lower is fainter)."] = "مدى وضوح الصف المرشّح (الأقل أبهت).",
  ["How visible an out-of-range enemy plate stays."] = "مدى وضوح لوحة العدو خارج المدى.",
  ["How visible chat stays while faded."] = "مدى وضوح الدردشة أثناء الخفوت.",
  ["How visible the faded header and backdrop are."] = "مدى وضوح الترويسة والخلفية المخفتتين.",
  ["How visible the faded micro menu and bag bar stay."] = "مدى وضوح القائمة المصغرة وشريط الحقائب المخفتين.",
  ["How visible the header and background are while the mouse is away."] = "مدى وضوح الترويسة والخلفية أثناء ابتعاد الفأرة.",
  ["How your current target's plate is marked."] = "كيف تُعلَّم لوحة هدفك الحالي.",
