  ["ID label colour"] = "لون تسمية المعرّف",
  ["ID label colours"] = "ألوان تسميات المعرّفات",
  ["ID label style"] = "نمط تسمية المعرّف",
  ["ID number colour"] = "لون رقم المعرّف",
  ["Icon border"] = "إطار الأيقونة",
  ["Icon shape"] = "شكل الأيقونة",
