  ["Icon size."] = "حجم الأيقونة.",
  ["Icon size; 0 follows the frame height."] = "حجم الأيقونة؛ 0 يتبع ارتفاع الإطار.",
  ["Icon spacing"] = "تباعد الأيقونات",
  ["Icon zoom"] = "تكبير الأيقونة",
  ["Icons per row on the custom bar."] = "الأيقونات لكل صف في الشريط المخصص.",
  ["Icons per row."] = "الأيقونات لكل صف.",
  ["If you are fighting when the countdown ends, it waits until you are out of combat."] = "إذا كنت تقاتل عند انتهاء العد التنازلي، ينتظر حتى تخرج من القتال.",
  ["If your character shares a name with an addon or a system word, it stays visible inside file paths in reports. Addon folder names and client words are already on this list."] = "إذا كان اسم شخصيتك يطابق اسم إضافة أو كلمة نظام، يبقى ظاهرًا داخل مسارات الملفات في التقارير. أسماء مجلدات الإضافات وكلمات العميل موجودة في هذه القائمة مسبقًا.",
  ["Ignore my own lines"] = "تجاهل أسطري",
  ["Important aura border colour"] = "لون إطار التأثيرات المهمة",
  ["Important cast glow colour"] = "لون توهج الإلقاءات المهمة",
  ["Important or purgeable buffs, right of the plate."] = "التعزيزات المهمة أو القابلة للتطهير، يمين اللوحة.",
  ["Imported NPC colour packs"] = "حزم ألوان NPC المستوردة",
  ["In Mythic raids only the 20 players in groups 1 to 4 are shown; benched players in groups 5 to 8 are left out."] = "في الغارات الأسطورية يظهر فقط 20 لاعبًا في المجموعات 1 إلى 4؛ ويُستبعد الاحتياطيون في المجموعات 5 إلى 8.",
  ["In Mythic+, hide reminders on keys at or above this level (0 never hides)."] = "في الأسطوري+، أخفِ التذكيرات على المفاتيح بهذا المستوى أو أعلى (0 لا يخفي أبدًا).",
  ["In Mythic+, how much enemy forces an enemy is worth (data from the M+ tracker)."] = "في الأسطوري+، كم تساوي قوات العدو لكل عدو (بيانات من متتبع M+).",
  ["In Mythic+, shows how much enemy forces each enemy is worth, next to its plate."] = "في الأسطوري+، يعرض بجانب اللوحة كم تساوي قوات العدو لكل عدو.",
  ["In arenas and battlegrounds Tab targets the nearest enemy player (an override binding; your own Tab comes back outside)."] = "في الساحات وساحات المعارك يستهدف Tab أقرب لاعب عدو (ارتباط تجاوز؛ يعود Tab الخاص بك خارجها).",
  ["In arenas, a coloured dot for each enemy that is targeting this member (the same colours as your arena frames)."] = "في الساحات، نقطة ملونة لكل عدو يستهدف هذا العضو (بألوان إطارات الساحة نفسها).",
  ["In category and list views, shows one empty slot with the free count instead of every empty slot."] = "في عرضي الفئات والقائمة، يعرض خانة فارغة واحدة بعدد الخانات الحرة بدلًا من كل الخانات الفارغة.",
  ["In combat, colour enemy plates by your threat. Tanks want aggro; everyone else wants none."] = "أثناء القتال، لوّن لوحات الأعداء حسب تهديدك. المدافعون يريدون التهديد؛ والجميع غيرهم لا يريدونه.",
  ["In game only"] = "داخل اللعبة فقط",
  ["In game only: this game version"] = "داخل اللعبة فقط: إصدار اللعبة هذا",
  ["Include addon compartment entries"] = "تضمين عناصر حجرة الإضافات",
  ["Include my character name"] = "تضمين اسم شخصيتي",
  ["Include other addons' errors in uploads"] = "تضمين أخطاء الإضافات الأخرى في الرفع",
  ["Include the loaded addon list in uploads"] = "تضمين قائمة الإضافات المحمّلة في الرفع",
  ["Includes your own frame in the party frames."] = "يضمّن إطارك في إطارات المجموعة.",
  ["Incoming heals"] = "العلاجات القادمة",
  ["Incoming: animation"] = "الوارد: الحركة",
  ["Incoming: direction"] = "الوارد: الاتجاه",
  ["Incoming: most lines per second"] = "الوارد: أقصى أسطر في الثانية",
  ["Incoming: on"] = "الوارد: مفعّل",
  ["Incoming: opacity"] = "الوارد: العتامة",
