  ["Indicator: resting (player)"] = "المؤشر: الراحة (اللاعب)",
  ["Indicators"] = "المؤشرات",
  ["Information bars (clock, FPS, latency, gold, currencies, durability, M+ score and more) and the XP / reputation / honor bar."] = "أشرطة المعلومات (الساعة، FPS، التأخير، الذهب، العملات، المتانة، تقييم M+ وغيرها) وشريط الخبرة / السمعة / الشرف.",
  ["Insanity bar colour"] = "لون شريط الجنون",
  ["Insert my keystone"] = "إدخال حجر مفتاحي",
  ["Inspect"] = "الفحص",
  ["Instance difficulty"] = "صعوبة الزنزانة",
  ["Interface font"] = "خط الواجهة",
  ["Interrupted / finished flash"] = "وميض المقاطعة / الانتهاء",
  ["Interrupted colour"] = "لون المقاطعة",
  ["Interrupted colour of plate cast bars."] = "لون المقاطعة لأشرطة إلقاء اللوحات.",
  ["Interrupted-by time"] = "مدة «قاطعه»",
  ["Invite on keyword"] = "الدعوة بكلمة مفتاحية",
  ["Invite words"] = "كلمات الدعوة",
  ["Invites friends, Battle.net friends and guild members who whisper one of your words. Never strangers; never during chat lockdown."] = "يدعو الأصدقاء وأصدقاء Battle.net وأعضاء النقابة الذين يهمسون بإحدى كلماتك. لا يدعو الغرباء أبدًا؛ ولا أثناء إقفال الدردشة.",
  ["Item IDs shown in the Pinned category and never sold as junk. Use Pin mode in the bags to add items by clicking."] = "معرّفات الأغراض المعروضة في فئة المثبتة والتي لا تُباع كخردة أبدًا. استخدم وضع التثبيت في الحقائب لإضافة الأغراض بالنقر.",
  ["Item IDs shown on the Action Bars item bar and the Cooldown Manager custom bar, in order (for example Healthstone 5512, healing potions, quest items, toys)."] = "معرّفات الأغراض المعروضة على شريط أغراض Action Bars والشريط المخصص لمدير فترات التهدئة، بالترتيب (مثل حجر الصحة 5512، وجرعات العلاج، وأغراض المهام، والألعاب).",
  ["Item IDs that say when they are ready again (Healthstone is 5512). Potions you add here work the same."] = "معرّفات الأغراض التي تُعلم عند جاهزيتها مجددًا (حجر الصحة هو 5512). الجرعات التي تضيفها هنا تعمل بالطريقة نفسها.",
  ["Item IDs treated as junk. Use Junk mode in the bags to add items by clicking."] = "معرّفات الأغراض المعاملة كخردة. استخدم وضع الخردة في الحقائب لإضافة الأغراض بالنقر.",
  ["Item IDs whose use is never shown (for example a Healthstone, 5512)."] = "معرّفات الأغراض التي لا يُعرض استخدامها أبدًا (مثل حجر الصحة، 5512).",
  ["Item bar"] = "شريط الأغراض",
  ["Item bar button size"] = "حجم أزرار شريط الأغراض",
  ["Item bar buttons per row"] = "أزرار كل صف في شريط الأغراض",
  ["Item bar fade opacity"] = "عتامة خفوت شريط الأغراض",
  ["Item bar fade until mouse-over"] = "خفوت شريط الأغراض حتى مرور الفأرة",
