  ["Keeps each whisper conversation in its own tab of a small window with a reply box. Never pops up in combat."] = "يُبقي كل محادثة همس في تبويب خاص بنافذة صغيرة مع مربع رد. لا ينبثق أبدًا أثناء القتال.",
  ["Keeps history across reloads and logins. Lines the game kept secret are never stored."] = "يحتفظ بالسجل عبر إعادة التحميل وتسجيل الدخول. الأسطر التي أبقتها اللعبة سرية لا تُخزَّن أبدًا.",
  ["Keeps recent chat lines so you can search them by text, channel, player and date (/pui chat history)."] = "يحتفظ بأسطر الدردشة الأخيرة لتبحث فيها بالنص والقناة واللاعب والتاريخ (/pui chat history).",
  ["Keeps the last 200 Phoenix bus signals (module enabled, profile changes, settings) for /pui trace. Off costs nothing."] = "يحتفظ بآخر 200 إشارة من ناقل Phoenix (تفعيل الوحدات، تغييرات الملف الشخصي، الإعدادات) لـ /pui trace. الإيقاف لا يكلف شيئًا.",
