  ["Mouse wheel cycles overlaps"] = "عجلة الفأرة تتنقل بين المتداخلات",
  ["Move Blizzard windows"] = "نقل نوافذ Blizzard",
  ["Moves the DR tray left or right."] = "يحرك درج DR يمينًا أو يسارًا.",
  ["Moves the DR tray up or down."] = "يحرك درج DR للأعلى أو للأسفل.",
  ["Movie subtitles"] = "ترجمة الأفلام",
  ["Moving strip: new casts push the old ones along. Still and fade: icons stay put and fade out."] = "شريط متحرك: الإلقاءات الجديدة تدفع القديمة. ثابت وإخفات: تبقى الأيقونات في مكانها وتخفت.",
  ["My reminder list"] = "قائمة تذكيراتي",
  ["My reminders"] = "تذكيراتي",
  ["My roles per spec"] = "أدواري لكل تخصص",
  ["Mythic raids: groups 1 to 4 only"] = "الغارات الأسطورية: المجموعات 1 إلى 4 فقط",
  ["Mythic+ block"] = "كتلة الأسطوري+",
  ["Mythic+ block on top"] = "كتلة الأسطوري+ في الأعلى",
  ["Mythic+ block: timer with +2/+3 marks and pace, enemy forces, boss splits, deaths, battle res and Bloodlust, keystones and a run summary."] = "كتلة الأسطوري+: مؤقت بعلامات +2/+3 والإيقاع، وقوات الأعداء، وأجزاء الزعماء، والوفيات، وإحياء المعركة والتعطش للدماء، وأحجار المفاتيح، وملخص الجولة.",
  ["Mythic+ enemy forces"] = "قوات أعداء الأسطوري+",
  ["Mythic+ key level, arena, battleground, delve or raid when the game shows it."] = "مستوى مفتاح الأسطوري+ أو الساحة أو ساحة المعركة أو الغور أو الغارة عندما تعرضه اللعبة.",
  ["Mythic+ keystone"] = "حجر مفتاح الأسطوري+",
  ["Mythic+ run summary"] = "ملخص جولة الأسطوري+",
  ["Mythic+ score"] = "تقييم الأسطوري+",
  ["Mythic+ timer: when another addon does this"] = "مؤقت الأسطوري+: عندما تفعل إضافة أخرى ذلك",
  ["NPC titles"] = "ألقاب NPC",
  ["Name colour"] = "لون الاسم",
  ["Name position"] = "موضع الاسم",
  ["Name size"] = "حجم الاسم",
  ["Name the fight"] = "تسمية المعركة",
  ["Nameplates"] = "لوحات الأسماء",
  ["Names"] = "الأسماء",
  ["Names longer than the limit become their initials (Shadow Word: Pain -> SWP)."] = "الأسماء الأطول من الحد تصبح أحرفها الأولى (Shadow Word: Pain -> SWP).",
  ["Names of the NPC colour packs to add after your own rules (your own lines always win)."] = "أسماء حزم ألوان NPC المضافة بعد قواعدك (أسطرك تفوز دائمًا).",
  ["Names your oldest application on the panel and highlights its row."] = "يسمّي أقدم طلب لك على اللوحة ويميّز صفه.",
  ["Neutral colour"] = "لون المحايد",
  ["Never collect"] = "عدم الجمع أبدًا",
  ["Never dim these spells"] = "عدم تعتيم هذه التعاويذ أبدًا",
  ["Never leave in combat"] = "عدم المغادرة أثناء القتال أبدًا",
  ["New columns are added to the left instead of the right."] = "تُضاف الأعمدة الجديدة إلى اليسار بدلًا من اليمين.",
  ["New group sound"] = "صوت المجموعة الجديدة",
  ["New item glow"] = "توهج الأغراض الجديدة",
  ["New items category"] = "فئة الأغراض الجديدة",
  ["New members are added above instead of below."] = "يُضاف الأعضاء الجدد في الأعلى بدلًا من الأسفل.",
  ["New-error popup"] = "نافذة الخطأ الجديد",
  ["Newest icon glow"] = "توهج أحدث أيقونة",
  ["Next abilities list"] = "قائمة القدرات التالية",
  ["Normal colour"] = "اللون العادي",
  ["Normal text size in this area."] = "حجم النص العادي في هذه المنطقة.",
  ["Not enough power colour"] = "لون عدم كفاية الطاقة",
  ["Notes"] = "الملاحظات",
  ["Notes in the panel"] = "الملاحظات في اللوحة",
  ["Notes scale"] = "مقياس الملاحظات",
  ["Notes window"] = "نافذة الملاحظات",
  ["Notice time"] = "مدة الإشعار",
  ["Notifications: animation"] = "الإشعارات: الحركة",
  ["Notifications: direction"] = "الإشعارات: الاتجاه",
  ["Notifications: most lines per second"] = "الإشعارات: أقصى أسطر في الثانية",
  ["Notifications: on"] = "الإشعارات: مفعّلة",
  ["Notifications: opacity"] = "الإشعارات: العتامة",
  ["Notifications: scroll height"] = "الإشعارات: ارتفاع التمرير",
  ["Notifications: text align"] = "الإشعارات: محاذاة النص",
  ["Notifications: text size"] = "الإشعارات: حجم النص",
  ["Notifications: time on screen (s)"] = "الإشعارات: الوقت على الشاشة (ث)",
  ["Number font"] = "خط الأرقام",
  ["Number format"] = "تنسيق الأرقام",
  ["Number of icons"] = "عدد الأيقونات",
  ["Number style"] = "نمط الأرقام",
  ["Numbers follow FrameSort"] = "الأرقام تتبع FrameSort",
  ["Objective progress sound"] = "صوت تقدم الهدف",
  ["Objective tracker"] = "متتبع الأهداف",
  ["Objectives go from red to green as their count fills."] = "تتحول الأهداف من الأحمر إلى الأخضر مع امتلاء عدّادها.",
  ["Off while a boss mod keeps stats"] = "مُعطّل أثناء احتفاظ إضافة زعماء بالإحصاءات",
  ["Off-tank colour"] = "لون المدافع الثاني",
  ["Off: the All filter lists only Blizzard elements you changed; the Blizzard filter always lists them all."] = "عند الإيقاف: مرشح الكل يدرج فقط عناصر Blizzard التي غيّرتها؛ ومرشح Blizzard يدرجها كلها دائمًا.",
  ["On a boss, shows your best saved pull on the same boss and difficulty in the title, and after the pull how you did against it."] = "على الزعيم، يعرض في العنوان أفضل سحب محفوظ لك على الزعيم والصعوبة نفسيهما، وبعد السحب كيف كان أداؤك مقارنة به.",
  ["On: the full log goes to the dashboard, other addons' errors included, so conflicts with Phoenix can be found (same privacy filters: names and paths scrubbed). Off: only Phoenix's own errors leave this PC."] = "عند التفعيل: يذهب السجل الكامل إلى لوحة التحكم، بما فيه أخطاء الإضافات الأخرى، لاكتشاف التعارضات مع Phoenix (مرشحات الخصوصية نفسها: تُمحى الأسماء والمسارات). عند الإيقاف: لا تغادر هذا الحاسوب إلا أخطاء Phoenix.",
  ["One NPC per line: its NPC id or exact name, a colour, then optionally a size and 'glow'. Examples: 185680:B07CFF  -  Void Acolyte:B07CFF:1.1  -  Explosive:FF5468:1.2:glow. The first line for an NPC wins. In some restricted content the game hides NPC ids and names; then a rule waits until they are visible."] = "NPC واحد لكل سطر: معرّفه أو اسمه الدقيق، ثم لون، ثم اختياريًا حجم و'glow'. أمثلة: 185680:B07CFF  -  Void Acolyte:B07CFF:1.1  -  Explosive:FF5468:1.2:glow. يفوز السطر الأول لكل NPC. في بعض المحتوى المقيد تخفي اللعبة معرّفات NPC وأسماءها؛ فتنتظر القاعدة حتى تظهر.",
  ["One binding per row. Pick a modifier, a mouse button or a key, and what it does: target, menu, focus, assist, cast a spell, run a macro or use an item. Keys work while the mouse is over a frame. Each spec can keep its own list (Editing as). Changes made in combat apply as soon as combat ends."] = "ارتباط واحد لكل صف. اختر مفتاح تعديل أو زر فأرة أو مفتاحًا، وما يفعله: استهداف، قائمة، تركيز، مساعدة، إلقاء تعويذة، تشغيل ماكرو أو استخدام غرض. تعمل المفاتيح والفأرة فوق الإطار. لكل تخصص قائمته (التحرير كـ). التغييرات أثناء القتال تُطبق فور انتهائه.",
  ["One button per line: bar.button: options. Options: nohotkey, nomacro, nocount, hide, alpha=0.5, glow=none|pulse|solid|flash. Example: 1.12:nohotkey,alpha=0.6"] = "زر واحد لكل سطر: bar.button: options. الخيارات: nohotkey، nomacro، nocount، hide، alpha=0.5، glow=none|pulse|solid|flash. مثال: 1.12:nohotkey,alpha=0.6",
  ["One colour for every glow: the theme's accent. Off keeps each glow's own colour."] = "لون واحد لكل توهج: لون تمييز السمة. الإيقاف يُبقي لون كل توهج.",
  ["One font everywhere"] = "خط واحد في كل مكان",
  ["One large icon in the middle for a big personal or external defensive."] = "أيقونة كبيرة واحدة في الوسط لدفاعي شخصي أو خارجي كبير.",
  ["One line each time your pet becomes unhappy."] = "سطر واحد في كل مرة يصبح فيها حيوانك الأليف غير سعيد.",
  ["One line each: \"Boss name: text\". Lines starting with \"*:\" show for every boss."] = "سطر لكل واحد: \"Boss name: text\". الأسطر التي تبدأ بـ \"*:\" تظهر لكل زعيم.",
  ["One line each: \"Original name = New text\". Blank new text hides the name."] = "سطر لكل واحد: \"Original name = New text\". النص الجديد الفارغ يخفي الاسم.",
  ["One line each: \"spellID: sound\" (a Phoenix or shared sound name), optionally \", removed\" or \", stacks\". The game plays it itself, so it works for private boss debuffs too."] = "سطر لكل واحد: \"spellID: sound\" (اسم صوت Phoenix أو مشترك)، واختياريًا \", removed\" أو \", stacks\". تشغّله اللعبة بنفسها، لذا يعمل مع التأثيرات الضارة الخاصة بالزعماء أيضًا.",
  ["One line per boss, by name or encounter ID: \"off\" hides Pulse bars, \"bars=4\" limits bars, \"hud=on\" or \"hud=off\" for the next-abilities list. Example: Dimensius: bars=4 hud=on"] = "سطر لكل زعيم، بالاسم أو معرّف المواجهة: \"off\" يخفي أشرطة Pulse، و\"bars=4\" يحدد الأشرطة، و\"hud=on\" أو \"hud=off\" لقائمة القدرات التالية. مثال: Dimensius: bars=4 hud=on",
  ["One line per click: \"1: target\", \"2: focus\", \"shift-1: spell:Polymorph\", \"ctrl-3: macro:/cast [@arena1] Kick\", \"3: none\". Applied when you leave combat."] = "سطر لكل نقرة: \"1: target\"، \"2: focus\"، \"shift-1: spell:Polymorph\"، \"ctrl-3: macro:/cast [@arena1] Kick\"، \"3: none\". يُطبق عند مغادرة القتال.",
  ["One line per reminder: key: sound=SoundName icon=IconID (for example 'oil: sound=Phoenix icon=463543'). Keys: intellect, stamina, lethal, pet, oil, talents, custom12345 ..."] = "سطر لكل تذكير: key: sound=SoundName icon=IconID (مثل 'oil: sound=Phoenix icon=463543'). المفاتيح: intellect، stamina، lethal، pet، oil، talents، custom12345 ...",
  ["One line per spec: spec ID = roles, e.g. '105 = HEALER, DPS'. Used when Roles per spec is 'My own list'."] = "سطر لكل تخصص: معرّف التخصص = الأدوار، مثل '105 = HEALER, DPS'. يُستخدم عندما تكون الأدوار لكل تخصص «قائمتي».",
  ["One per line as itemID=Category (a built-in id such as consumables, or the name of one of your rules)."] = "واحد لكل سطر بصيغة itemID=Category (معرّف مدمج مثل consumables، أو اسم إحدى قواعدك).",
  ["One per line: a spell ID, optionally followed by :name (for example 1234:Flask). Shows when you lack that buff."] = "واحد لكل سطر: معرّف تعويذة، يليه اختياريًا :name (مثل 1234:Flask). يظهر عندما ينقصك ذلك التعزيز.",
  ["One search across friends, guild and recent players, with sort and actions, beside the friends list."] = "بحث واحد عبر الأصدقاء والنقابة واللاعبين الأخيرين، مع الترتيب والإجراءات، بجانب قائمة الأصدقاء.",
  ["One section per addon (collapsible, with counts, first and last seen and the session), or a single newest-first list."] = "قسم لكل إضافة (قابل للطي، مع الأعداد وأول وآخر ظهور والجلسة)، أو قائمة واحدة الأحدث أولًا.",
  ["One setting for every place roles are set: manual, the role your spec plays, or your own list below. Auto stands down while BigWigs sets roles."] = "إعداد واحد لكل مكان تُحدد فيه الأدوار: يدوي، أو دور تخصصك، أو قائمتك أدناه. التلقائي يتنحى بينما يحدد BigWigs الأدوار.",
  ["One switch for every chat announcement Phoenix modules can make. Modules only pick what to say; where it goes is set here."] = "مفتاح واحد لكل إعلانات الدردشة التي قد تصدرها وحدات Phoenix. الوحدات تختار ما تقوله فقط؛ ووجهته تُحدد هنا.",
  ["Online friends count on the minimap; hover it for the list."] = "عدد الأصدقاء المتصلين على الخريطة المصغرة؛ مرر فوقه للقائمة.",
  ["Online friends' names in their class colour."] = "أسماء الأصدقاء المتصلين بلون فئتهم.",
  ["Only DR I can trigger"] = "فقط DR التي أستطيع تفعيلها",
  ["Only cooldowns longer than (s)"] = "فقط فترات التهدئة الأطول من (ث)",
  ["Only debuffs your class and spec can remove, or any dispellable debuff (useful to call for help)."] = "فقط التأثيرات الضارة التي تستطيع فئتك وتخصصك إزالتها، أو أي تأثير قابل للتبديد (مفيد لطلب المساعدة).",
  ["Only in combat"] = "أثناء القتال فقط",
  ["Only online players in the search panel."] = "اللاعبون المتصلون فقط في لوحة البحث.",
  ["Only tanks and healers get a role marker."] = "فقط المدافعون والمعالجون يحصلون على علامة دور.",
  ["Opacity"] = "العتامة",
  ["Opacity of a frame whose unit is out of range."] = "عتامة الإطار الذي وحدته خارج المدى.",
  ["Opacity of bar 1 while faded."] = "عتامة الشريط 1 أثناء الخفوت.",
  ["Opacity of bar 10 while faded."] = "عتامة الشريط 10 أثناء الخفوت.",
  ["Opacity of bar 2 while faded."] = "عتامة الشريط 2 أثناء الخفوت.",
  ["Opacity of bar 3 while faded."] = "عتامة الشريط 3 أثناء الخفوت.",
  ["Opacity of bar 4 while faded."] = "عتامة الشريط 4 أثناء الخفوت.",
  ["Opacity of bar 5 while faded."] = "عتامة الشريط 5 أثناء الخفوت.",
  ["Opacity of bar 6 while faded."] = "عتامة الشريط 6 أثناء الخفوت.",
  ["Opacity of bar 7 while faded."] = "عتامة الشريط 7 أثناء الخفوت.",
  ["Opacity of bar 8 while faded."] = "عتامة الشريط 8 أثناء الخفوت.",
  ["Opacity of bar 9 while faded."] = "عتامة الشريط 9 أثناء الخفوت.",
  ["Opacity of out-of-range frames."] = "عتامة الإطارات خارج المدى.",
  ["Opacity of plates that are not your target while you have one; 1 keeps them fully visible."] = "عتامة اللوحات التي ليست هدفك عندما يكون لديك هدف؛ 1 يُبقيها مرئية بالكامل.",
  ["Opacity of the bars."] = "عتامة الأشرطة.",
  ["Opacity of the chat panel."] = "عتامة لوحة الدردشة.",
  ["Opacity of the dark background behind Phoenix bars."] = "عتامة الخلفية الداكنة خلف أشرطة Phoenix.",
  ["Opacity of the empty part of each bar."] = "عتامة الجزء الفارغ من كل شريط.",
  ["Opacity of the health fill."] = "عتامة ملء الصحة.",
  ["Opacity of the item bar while faded."] = "عتامة شريط الأغراض أثناء الخفوت.",
  ["Opacity of the pet bar while faded."] = "عتامة شريط الحيوان الأليف أثناء الخفوت.",
  ["Opacity of the stance bar while faded."] = "عتامة شريط الوضعيات أثناء الخفوت.",
  ["Opacity of the text."] = "عتامة النص.",
  ["Opacity of the vehicle exit button while faded."] = "عتامة زر الخروج من المركبة أثناء الخفوت.",
  ["Opacity of the whole tracker."] = "عتامة المتتبع كله.",
  ["Opacity out of combat"] = "العتامة خارج القتال",
  ["Opacity used when the where-to-show rule hides the frame (0 = invisible, higher = faded)."] = "العتامة المستخدمة عندما تخفي قاعدة مكان الإظهار الإطار (0 = غير مرئي، الأعلى = مخفت).",
  ["Opacity used when the where-to-show rule hides the frames (0 = invisible). They stay clickable in combat because the game locks that."] = "العتامة المستخدمة عندما تخفي قاعدة مكان الإظهار الإطارات (0 = غير مرئية). تبقى قابلة للنقر أثناء القتال لأن اللعبة تقفل ذلك.",
  ["Open Phoenix Studio button"] = "زر فتح Phoenix Studio",
  ["Open a blocked report in the copy box"] = "فتح التقرير المحظور في مربع النسخ",
  ["Open containers"] = "فتح الحاويات",
  ["Open key"] = "مفتاح الفتح",
  ["Open recap when I die"] = "فتح الملخص عندما أموت",
  ["Open the bin by"] = "فتح الحاوية بـ",
  ["Open the scoreboard after a battleground"] = "فتح لوحة النتائج بعد ساحة المعركة",
  ["Open the viewer on a new error"] = "فتح العارض عند خطأ جديد",
  ["Opens Phoenix's scoreboard when a battleground ends."] = "يفتح لوحة نتائج Phoenix عند انتهاء ساحة المعركة.",
  ["Opens at"] = "يُفتح عند",
  ["Opens beside Blizzard's PvP window, or only with /pui pvp card."] = "يُفتح بجانب نافذة PvP من Blizzard، أو فقط بـ /pui pvp card.",
  ["Opens lootable bag items (caches, satchels) one at a time out of combat. Hold Shift to keep them closed."] = "يفتح أغراض الحقائب القابلة للنهب (الكنوز، الحقائب) واحدًا تلو الآخر خارج القتال. اضغط Shift مطولًا لإبقائها مغلقة.",
  ["Opens the error viewer by itself. Never during combat: it waits until the fight ends."] = "يفتح عارض الأخطاء من تلقاء نفسه. أبدًا أثناء القتال: ينتظر حتى انتهاء المعركة.",
  ["Opens your death recap automatically when you die."] = "يفتح ملخص موتك تلقائيًا عندما تموت.",
  ["Optional: the season's achievement ID, so the count comes from the game. 0 = automatic (Gladiator) or Phoenix's count."] = "اختياري: معرّف إنجاز الموسم ليأتي العدد من اللعبة. 0 = تلقائي (المصارع) أو عدد Phoenix.",
  ["Options mode"] = "وضع الخيارات",
  ["Oracle"] = "Oracle",
