  ["Order of Phoenix's list, e.g. 'mprating desc, age asc'. Empty keeps Blizzard's order."] = "ترتيب قائمة Phoenix، مثل 'mprating desc, age asc'. الفراغ يُبقي ترتيب Blizzard.",
  ["Order of categories, highest first. Words: cc, defensive, important. Leave one out to never show it (\"cc\" alone shows only crowd control)."] = "ترتيب الفئات، الأعلى أولًا. الكلمات: cc، defensive، important. احذف واحدة لعدم إظهارها أبدًا (\"cc\" وحدها تعرض التحكم بالحشود فقط).",
