  ["Pet your interrupt"] = "الحيوان الأليف: مقاطعتك",
  ["Pet: where to show"] = "الحيوان الأليف: مكان الإظهار",
  ["Pets, guardians and other summons controlled by players get a smaller plate."] = "الرفقاء والحراس وغيرهم من المستدعَين الذين يتحكم بهم اللاعبون يحصلون على لوحة أصغر.",
  ["Phoenix action bars hide while a controller is active, for controller addons that bring their own bars."] = "تختفي أشرطة أوامر Phoenix أثناء نشاط وحدة التحكم، لملحقات وحدة التحكم التي تجلب أشرطتها الخاصة.",
  ["Phoenix action bars hide while you are inside a player house and come back when you leave."] = "تختفي أشرطة أوامر Phoenix أثناء وجودك داخل منزل لاعب وتعود عند مغادرتك.",
  ["Phoenix action bars with paging, where-to-show rules, mouse-over fade, keybind mode, cooldowns, range colouring and proc glow, plus stance, pet, vehicle exit and item bars."] = "أشرطة أوامر Phoenix مع تقليب الصفحات وقواعد أين تظهر وتلاشي حتى التمرير ووضع الاختصارات وفترات التهدئة وتلوين المدى وتوهج التفعيل، إضافة إلى أشرطة الوضعيات والرفيق والخروج من المركبة والأغراض.",
  ["Phoenix background and border on tooltips; off keeps Blizzard's look."] = "خلفية Phoenix وحدّها على التلميحات؛ الإيقاف يبقي مظهر Blizzard.",
  ["Phoenix bank window"] = "نافذة مصرف Phoenix",
  ["Phoenix bars and names use the class colours below instead of the game's."] = "تستخدم أشرطة Phoenix وأسماؤها ألوان الفئات أدناه بدل ألوان اللعبة.",
  ["Phoenix bars for breath, fatigue and feign death timers."] = "أشرطة Phoenix لمؤقتات التنفس والإرهاق وتظاهر الموت.",
  ["Phoenix border and tabs"] = "حد Phoenix وعلاماته",
  ["Phoenix boxes; the check mark takes the accent colour."] = "مربعات Phoenix؛ علامة الاختيار تأخذ لون التمييز.",
  ["Phoenix builds this many plates out of combat so big pulls never build frames mid-fight."] = "يبني Phoenix هذا العدد من اللوحات خارج القتال حتى لا تُبنى إطارات وسط القتال في السحبات الكبيرة.",
  ["Phoenix button face on Blizzard panel buttons."] = "وجه أزرار Phoenix على أزرار لوحات Blizzard.",
  ["Phoenix chat bubbles in the open world (Blizzard locks them inside instances)."] = "فقاعات دردشة Phoenix في العالم المفتوح (تقفلها Blizzard داخل المثيلات).",
  ["Phoenix draws this frame, Blizzard shows the default frame, or hidden shows neither."] = "يرسم Phoenix هذا الإطار، أو تعرض Blizzard الإطار الافتراضي، أو المخفي لا يعرض أيًّا منهما.",
  ["Phoenix draws your buffs and debuffs in two movable rows, or Blizzard's default buff frame stays."] = "يرسم Phoenix التعزيزات والضعف في صفّين قابلين للتحريك، أو يبقى إطار التعزيزات الافتراضي من Blizzard.",
  ["Phoenix dropdown boxes with an accent arrow."] = "قوائم Phoenix المنسدلة بسهم بلون التمييز.",
  ["Phoenix ember backdrop behind mount and pet models."] = "خلفية جمر Phoenix خلف نماذج المطايا والرفقاء.",
  ["Phoenix ember backdrop behind the character model."] = "خلفية جمر Phoenix خلف نموذج الشخصية.",
  ["Phoenix emoji art"] = "رسوم الوجوه التعبيرية من Phoenix",
  ["Phoenix error reports go to the vq8s.com dashboard through the Companion app (and the export string works). See exactly what leaves this PC with Preview on the error reporter. Nothing is shared while off."] = "تُرسل تقارير أخطاء Phoenix إلى لوحة vq8s.com عبر تطبيق Companion (وسلسلة التصدير تعمل). شاهد بالضبط ما يغادر هذا الحاسوب عبر المعاينة في مُبلِّغ الأخطاء. لا يُشارك شيء أثناء الإيقاف.",
  ["Phoenix font on cinematic subtitles."] = "خط Phoenix على ترجمات المشاهد السينمائية.",
  ["Phoenix fonts and bars on top-centre and minimap widgets and the encounter power bar."] = "خطوط Phoenix وأشرطته على أدوات أعلى الوسط والخريطة المصغرة وشريط طاقة المواجهة.",
  ["Phoenix fonts on raid warnings, boss emotes and the red error text."] = "خطوط Phoenix على تحذيرات الغارة وتعبيرات الزعماء ونص الأخطاء الأحمر.",
  ["Phoenix frame skin for Details! windows when that addon is installed."] = "مظهر إطارات Phoenix لنوافذ Details! عند تثبيت ذلك الملحق.",
  ["Phoenix frame skin for Pawn when that addon is installed."] = "مظهر إطارات Phoenix لـ Pawn عند تثبيت ذلك الملحق.",
  ["Phoenix frame skin for Plater options when that addon is installed."] = "مظهر إطارات Phoenix لخيارات Plater عند تثبيت ذلك الملحق.",
  ["Phoenix frame skin for WeakAuras options when that addon is installed."] = "مظهر إطارات Phoenix لخيارات WeakAuras عند تثبيت ذلك الملحق.",
  ["Phoenix input boxes with a hairline border."] = "مربعات إدخال Phoenix بحد رفيع.",
  ["Phoenix keybinds"] = "اختصارات Phoenix",
  ["Phoenix look for Blizzard's windows, menus, tooltips and popups (their own layout and features, your theme), and Details!, Pawn, WeakAuras and Plater; each has its own switch."] = "مظهر Phoenix لنوافذ Blizzard وقوائمها وتلميحاتها ونوافذها المنبثقة (بتخطيطها وميزاتها الخاصة وسمتك)، وDetails! وPawn وWeakAuras وPlater؛ لكلٍّ منها مفتاحه الخاص.",
  ["Phoenix look for every context menu and dropdown list, including the damage meter's."] = "مظهر Phoenix لكل قائمة سياق وقائمة منسدلة، بما فيها قائمة عدّاد الضرر.",
  ["Phoenix look on Blizzard's meter"] = "مظهر Phoenix على عدّاد Blizzard",
  ["Phoenix look on flyouts"] = "مظهر Phoenix على القوائم المنبثقة",
  ["Phoenix minimap: shape, border, texts, coordinates, queue countdown, addon button bin and more."] = "خريطة Phoenix المصغرة: الشكل والحد والنصوص والإحداثيات والعد التنازلي للطابور وحاوية أزرار الملحقات والمزيد.",
  ["Phoenix nameplates: enemy and friendly styles, threat and NPC colours, cast bars with your interrupt, aura lanes, target and focus highlights, quest, execute and Mythic+ forces indicators."] = "لوحات أسماء Phoenix: أنماط الأعداء والحلفاء وألوان التهديد والشخصيات غير اللاعبة وأشرطة الإلقاء مع مقاطعتك ومسارات التأثيرات وتمييز الهدف والتركيز ومؤشرات المهام والإجهاز وقوات الأسطوري+.",
  ["Phoenix only restyles the cooldown icons and bars; their places, sizes and which ones show stay as Blizzard's Cooldown Manager sets them (from the game's next layout pass). The safest mode for testing."] = "يعيد Phoenix تنسيق أيقونات وأشرطة فترات التهدئة فقط؛ تبقى أماكنها وأحجامها وما يظهر منها كما يضبطها مدير فترات التهدئة من Blizzard (من دورة التخطيط التالية للعبة). أكثر الأوضاع أمانًا للاختبار.",
  ["Phoenix panel"] = "لوحة Phoenix",
  ["Phoenix panel on Blizzard's tutorial help tips."] = "لوحة Phoenix على تلميحات المساعدة التعليمية من Blizzard.",
  ["Phoenix party and raid frames: layouts by group size, sorting, role icons, dispel highlight, aura icons, corner indicators, private auras, heal prediction, range fade and a test mode."] = "إطارات المجموعة والغارة من Phoenix: تخطيطات حسب حجم المجموعة والفرز وأيقونات الأدوار وتمييز التبديد وأيقونات التأثيرات ومؤشرات الزوايا والتأثيرات الخاصة وتوقع الشفاء وتلاشي المدى ووضع الاختبار.",
