  ["Plays a sound when a new group that fits you shows up in a refreshed search."] = "يشغّل صوتًا عند ظهور مجموعة جديدة تناسبك في بحث محدّث.",
  ["Plays a sound when a reminder appears."] = "يشغّل صوتًا عند ظهور تذكير.",
