  ["Plays an extra ready-check sound when the invite appears."] = "يشغّل صوت فحص جاهزية إضافيًا عند ظهور الدعوة.",
  ["Plays this sound with the line (at most once every 0.3 s per row)."] = "يشغّل هذا الصوت مع السطر (مرة كل 0.3 ث لكل صف على الأكثر).",
  ["Pointing at any bar that fades until mouse-over shows every such bar at once."] = "الإشارة إلى أي شريط يتلاشى حتى التمرير تُظهر كل هذه الأشرطة معًا.",
