  ["Press this key to open or close Phoenix settings. Empty means no key."] = "اضغط هذا المفتاح لفتح إعدادات Phoenix أو إغلاقها. الفارغ يعني بلا مفتاح.",
  ["Press this key to open or close Studio. Empty means no key. Your own key bindings are untouched."] = "اضغط هذا المفتاح لفتح Studio أو إغلاقه. الفارغ يعني بلا مفتاح. اختصاراتك الخاصة لا تُمس.",
  ["Presses Sign Up on Blizzard's sign-up window with your roles. Hold Shift while signing up to choose yourself. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "يضغط «التسجيل» في نافذة التسجيل من Blizzard بأدوارك. اضغط Shift مطولًا أثناء التسجيل لتختار بنفسك. تشغّل Blizzard هذه النافذة بشيفرة محمية؛ مساعدة ملحق هنا قد تسبب نادرًا رسالة «حُظر إجراء الواجهة». مفعّل افتراضيًا لأنك اخترت ذلك؛ أوقفه إن رأيت تلك الرسالة.",
  ["Price font"] = "خط السعر",
  ["Priest colour"] = "لون الكاهن",
  ["Print event history"] = "طباعة سجل الأحداث",
  ["Print every Phoenix event (module changes, setting changes) to chat as it happens. For troubleshooting."] = "طباعة كل حدث في Phoenix (تغييرات الوحدات والإعدادات) في الدردشة عند حدوثه. لاستكشاف الأخطاء.",
  ["Print my roles"] = "طباعة أدواري",
  ["Prints a line when an invite is accepted for you."] = "يطبع سطرًا عند قبول دعوة نيابة عنك.",
  ["Prints a short line each time the layer key turns the layer on."] = "يطبع سطرًا قصيرًا في كل مرة يفعّل فيها مفتاح الطبقة الطبقة.",
  ["Prints kill or wipe, time and the compare with your best after every boss pull (only you see it)."] = "يطبع القتل أو الإبادة والوقت والمقارنة بأفضل نتيجة لك بعد كل سحبة زعيم (تراه أنت فقط).",
  ["Prints one line naming the profile after a specialization switch."] = "يطبع سطرًا واحدًا يذكر الملف الشخصي بعد تبديل التخصص.",
  ["Prints one line with a link that opens the viewer."] = "يطبع سطرًا واحدًا برابط يفتح العارض.",
  ["Prints the roles you signed up with, with icons, after a role check."] = "يطبع الأدوار التي سجلت بها مع الأيقونات بعد فحص الأدوار.",
