  ["Resource Bars' class resource, power and your cast bar sit under the player frame, or stay where you placed them in Studio. Turn the bars on in Resource Bars."] = "موارد الفئة والطاقة وشريط إلقائك من أشرطة الموارد تقع تحت إطار اللاعب، أو تبقى حيث وضعتها في Studio. فعّل الأشرطة في أشرطة الموارد.",
