  ["Resource bars"] = "أشرطة الموارد",
  ["Rested marker"] = "علامة الراحة",
  ["Restyled quest tracker with sorting, filters, super tracking, /way, the Mythic+ block on top and quest automation."] = "متتبع مهام معاد تنسيقه مع الفرز والمرشحات والتتبع الفائق والأمر /way وكتلة الأسطوري+ في الأعلى وأتمتة المهام.",
  ["Results shown"] = "النتائج المعروضة",
