  ["Role checks, sign-up confirm, double-click sign-up, role bar and the Enter button. Each part also has its own switch."] = "فحوص الأدوار وتأكيد التسجيل والتسجيل بالنقر المزدوج وشريط الأدوار وزر الدخول. لكل جزء مفتاحه الخاص أيضًا.",
  ["Role fit"] = "ملاءمة الدور",
  ["Role icons"] = "أيقونات الأدوار",
  ["Role icons for each member in tank, healer, damage order, with an optional class colour bar."] = "أيقونات أدوار كل عضو بترتيب مدافع، معالج، ضرر، مع شريط اختياري بلون الفئة.",
