  ["Rotation is a game setting; Phoenix records your old value and puts it back when you change this or turn the module off."] = "التدوير إعداد في اللعبة؛ يسجّل Phoenix قيمتك القديمة ويعيدها عند تغيير هذا أو إيقاف الوحدة.",
  ["Round N of 6 with a round clock, and your round record once the game shows it."] = "الجولة N من 6 مع ساعة الجولة، وسجل جولاتك بمجرد أن تعرضه اللعبة.",
  ["Row colour used when row colours are on. The sample rows on this page show it live."] = "لون الصف المستخدم عند تفعيل ألوان الصفوف. صفوف العينة في هذه الصفحة تعرضه مباشرة.",
  ["Row colours"] = "ألوان الصفوف",
  ["Row density"] = "كثافة الصفوف",
  ["Row height"] = "ارتفاع الصف",
  ["Row height of Phoenix's list."] = "ارتفاع صف قائمة Phoenix.",
  ["Row icon"] = "أيقونة الصف",
  ["Row spacing"] = "تباعد الصفوف",
  ["Rows"] = "الصفوف",
  ["Rows in Phoenix's list"] = "الصفوف في قائمة Phoenix",
  ["Rows per window."] = "الصفوف لكل نافذة.",
  ["Rows start at the anchor's left edge, its right edge, or are centred on it."] = "تبدأ الصفوف من الحافة اليسرى للمرساة أو اليمنى، أو تتوسطها.",
  ["Rule packs in use"] = "حزم القواعد المستخدمة",
