  ["Safe mode threshold"] = "عتبة الوضع الآمن",
  ["Sample Phoenix CPU use every 5 seconds and report modules that stay over budget."] = "أخذ عينة من استخدام Phoenix للمعالج كل 5 ثوانٍ والإبلاغ عن الوحدات التي تبقى فوق الميزانية.",
  ["Samples your own per-second figure once a second in combat for the pull graph."] = "يأخذ عينة من رقمك في الثانية مرة كل ثانية أثناء القتال لرسم السحبة.",
  ["Save bosses only"] = "حفظ الزعماء فقط",
