  ["Score if timed"] = "النقاط عند الإنجاز في الوقت",
  ["Score in tooltips"] = "النقاط في التلميحات",
  ["Score that gets the end colour; higher scores keep it."] = "النقاط التي تأخذ لون النهاية؛ النقاط الأعلى تحتفظ به.",
  ["Scoreboard columns"] = "أعمدة لوحة النتائج",
  ["Scrapping"] = "التفكيك",
  ["Screenshot on achievement"] = "لقطة شاشة عند الإنجاز",
  ["Scroll bars"] = "أشرطة التمرير",
  ["Scroll over stacked movers to pick the one underneath."] = "مرّر فوق المحرّكات المتراكبة لاختيار الذي تحتها.",
  ["Scroll over the minimap to zoom in and out."] = "مرّر فوق الخريطة المصغرة للتقريب والتبعيد.",
  ["Scroll rows with the mouse wheel"] = "تمرير الصفوف بعجلة الفأرة",
  ["Scrolling combat text in four areas, combat in and out, item ready, loot, money, reputation and XP. Turns Blizzard's combat text off while on."] = "نص قتالي متحرك في أربع مناطق: دخول القتال والخروج منه، وجاهزية الغرض، والغنائم، والمال، والسمعة، والخبرة. يوقف نص القتال من Blizzard أثناء التفعيل.",
  ["Scrolling combat text: when another addon does this"] = "النص القتالي المتحرك: عندما يقوم ملحق آخر بذلك",
  ["Search box"] = "مربع البحث",
  ["Search includes guild"] = "البحث يشمل النقابة",
  ["Search includes recent players"] = "البحث يشمل اللاعبين الأخيرين",
  ["Search panel"] = "لوحة البحث",
  ["Searchable history"] = "سجل قابل للبحث",
  ["Second tracking bar"] = "شريط التتبع الثاني",
  ["Seconds a finished or interrupted cast bar takes to fade."] = "الثواني التي يستغرقها شريط إلقاء منتهٍ أو مقطوع ليتلاشى.",
  ["Seconds before leaving."] = "الثواني قبل المغادرة.",
  ["Seconds before the popup closes after the mouse leaves."] = "الثواني قبل إغلاق النافذة المنبثقة بعد خروج الفأرة.",
  ["Seconds left until the DR resets, written by the game."] = "الثواني المتبقية حتى إعادة ضبط تناقص المفعول، كما تكتبها اللعبة.",
  ["Seconds the finished or interrupted cast stays visible while fading (0 hides it at once)."] = "الثواني التي يبقى فيها الإلقاء المنتهي أو المقطوع ظاهرًا أثناء التلاشي (0 يخفيه فورًا).",
  ["Sections start collapsed"] = "الأقسام تبدأ مطوية",
  ["Sell junk automatically"] = "بيع الخردة تلقائيًا",
  ["Sells grey items and items you marked as junk when you open a vendor. Off at first install; the Sell junk button works either way."] = "يبيع الأغراض الرمادية والأغراض التي وسمتها خردة عند فتح بائع. متوقف عند أول تثبيت؛ زر بيع الخردة يعمل في الحالتين.",
  ["Sells grey items when you open a vendor. While Vault is on, Vault's own junk setting decides instead."] = "يبيع الأغراض الرمادية عند فتح بائع. أثناء تفعيل Vault يقرر إعداد الخردة الخاص به بدلًا من ذلك.",
  ["Sends each installed addon's folder name, version and whether it is enabled, so the dashboard can rank possible conflicts. Nothing else about your addons or character."] = "يرسل اسم مجلد كل ملحق مثبت وإصداره وما إذا كان مفعّلًا، لتتمكن اللوحة من ترتيب التعارضات المحتملة. لا شيء آخر عن ملحقاتك أو شخصيتك.",
  ["Sends objective progress and completions through Phoenix announcements (the Quest topic there decides where)."] = "يرسل تقدم الأهداف وإكمالها عبر إعلانات Phoenix (موضوع المهام هناك يحدد الوجهة).",
  ["Sends the break through the announcement router (where it goes is set on the Announcements page; off until you turn it on there)."] = "يرسل الاستراحة عبر موجّه الإعلانات (الوجهة تُضبط في صفحة الإعلانات؛ متوقف حتى تفعّله هناك).",
  ["Sends your key to group members who also use Phoenix, so /keys can list theirs."] = "يرسل مفتاحك إلى أعضاء المجموعة الذين يستخدمون Phoenix أيضًا، ليتمكن الأمر /keys من عرض مفاتيحهم.",
  ["Sentinel notice"] = "إشعار Sentinel",
  ["Separators between blocks"] = "فواصل بين الكتل",
  ["Server time"] = "وقت الخادم",
  ["Set items (such as tier) show how many pieces of that set you are wearing."] = "أغراض الطقم (مثل الطبقة) تُظهر عدد قطع ذلك الطقم التي ترتديها.",
  ["Set pieces equipped"] = "قطع الطقم المجهّزة",
  ["Settings"] = "الإعدادات",
  ["Settings profile used by this character. Switching applies every setting immediately."] = "ملف الإعدادات الذي تستخدمه هذه الشخصية. التبديل يطبّق كل الإعدادات فورًا.",
  ["Shade the screen edges and the centre area where your character stands, to keep frames out of the way."] = "تظليل حواف الشاشة والمنطقة الوسطى حيث تقف شخصيتك، لإبعاد الإطارات عنها.",
  ["Shades the end of your cast that falls inside your network latency, so you can queue the next spell there."] = "يظلل نهاية إلقائك الواقعة ضمن زمن استجابة الشبكة، لتتمكن من وضع التعويذة التالية في الطابور هناك.",
  ["Shadowsight timer"] = "مؤقت بصيرة الظل",
  ["Shaman colour"] = "لون الشامان",
  ["Shape of action-button and cooldown icons: square, rounded, circle, hexagon and more (Phoenix masks)."] = "شكل أيقونات الأزرار وفترات التهدئة: مربع، مستدير الزوايا، دائرة، سداسي وغيرها (أقنعة Phoenix).",
  ["Share accepted quests"] = "مشاركة المهام المقبولة",
  ["Share my key with my group"] = "مشاركة مفتاحي مع مجموعتي",
  ["Share with other addons"] = "المشاركة مع الملحقات الأخرى",
  ["Shares quests you accept with your group when the game allows it."] = "يشارك المهام التي تقبلها مع مجموعتك عندما تسمح اللعبة.",
  ["Shift nudge step"] = "خطوة الإزاحة مع Shift",
  ["Shift+click an icon to print the spell name and ID in chat (off so hovering never spams)."] = "Shift+نقر على أيقونة يطبع اسم التعويذة ومعرّفها في الدردشة (متوقف حتى لا يملأ التمرير الدردشة).",
  ["Shift+click prints name and ID"] = "Shift+نقر يطبع الاسم والمعرّف",
  ["Short difficulty text inside instances, such as M+16, H, M, LFR or TW."] = "نص صعوبة قصير داخل المثيلات، مثل M+16 أو H أو M أو LFR أو TW.",
  ["Short item cooldowns are not announced."] = "لا يُعلن عن فترات تهدئة الأغراض القصيرة.",
  ["Short keybind text"] = "نص اختصارات قصير",
  ["Short numbers"] = "أرقام قصيرة",
  ["Shorten long ability names"] = "تقصير أسماء القدرات الطويلة",
  ["Shorten names longer than"] = "تقصير الأسماء الأطول من",
  ["Shortens key names so they fit: SHIFT-1 becomes S1, mouse button 4 becomes M4, mouse wheel up becomes WU."] = "يقصّر أسماء المفاتيح لتتسع: SHIFT-1 تصبح S1، وزر الفأرة 4 يصبح M4، وعجلة الفأرة للأعلى تصبح WU.",
  ["Show"] = "إظهار",
  ["Show 2v2"] = "إظهار 2v2",
  ["Show 3v3"] = "إظهار 3v3",
  ["Show BG Blitz"] = "إظهار BG Blitz",
  ["Show Edit Mode badges"] = "إظهار شارات وضع التحرير",
  ["Show IDs"] = "إظهار المعرّفات",
  ["Show IDs all the time, or only while a modifier key is held."] = "إظهار المعرّفات دائمًا، أو فقط أثناء الضغط على مفتاح تعديل.",
  ["Show Rated BG"] = "إظهار ساحات المعارك المصنفة",
  ["Show Solo Shuffle"] = "إظهار Solo Shuffle",
  ["Show Studio grid"] = "إظهار شبكة Studio",
  ["Show absorbs"] = "إظهار الامتصاص",
  ["Show bar 1 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 1 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 10 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 10 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 2 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 2 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 3 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 3 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 4 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 4 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 5 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 5 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 6 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 6 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 7 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 7 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 8 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 8 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show bar 9 everywhere, never, or only in the content, combat state, group and specialization you pick. Combat, vehicle, pet battle, mounted and skyriding apply instantly even in combat."] = "إظهار الشريط 9 في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة والتخصص الذي تختاره. القتال والمركبة ومعركة الرفقاء والامتطاء والطيران الحر تُطبّق فورًا حتى أثناء القتال.",
  ["Show empty buttons"] = "إظهار الأزرار الفارغة",
  ["Show enemy names"] = "إظهار أسماء الأعداء",
  ["Show every Blizzard element under All"] = "إظهار كل عناصر Blizzard تحت «الكل»",
  ["Show guild under friendly names"] = "إظهار النقابة تحت الأسماء الصديقة",
  ["Show in instances"] = "الإظهار في المثيلات",
  ["Show incoming heals"] = "إظهار الشفاء الوارد",
  ["Show my interrupt"] = "إظهار مقاطعتي",
  ["Show names"] = "إظهار الأسماء",
  ["Show only friends playing World of Warcraft: others are left out of the Phoenix list and dimmed on Blizzard's list (the game has no such filter of its own)."] = "إظهار الأصدقاء الذين يلعبون World of Warcraft فقط: يُستبعد الآخرون من قائمة Phoenix ويُعتَّمون في قائمة Blizzard (لا تملك اللعبة مرشحًا كهذا).",
  ["Show or collapse each built-in category (Pinned, New, Keystone shelf, Equipment sets, Junk and the rest)."] = "إظهار أو طي كل فئة مدمجة (المثبتة، الجديدة، رف المفاتيح، أطقم المعدات، الخردة وغيرها).",
  ["Show or hide tooltips while you are in combat."] = "إظهار التلميحات أو إخفاؤها أثناء القتال.",
  ["Show party frames when solo"] = "إظهار إطارات المجموعة عند اللعب منفردًا",
  ["Show realm time instead of your computer's time."] = "إظهار وقت العالم بدل وقت حاسوبك.",
  ["Show tenths of a second on the timer."] = "إظهار أعشار الثانية على المؤقت.",
  ["Show the age of your oldest application"] = "إظهار عمر أقدم طلب لك",
  ["Show the boss frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "إظهار إطار الزعيم في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هو مخفي الآن.",
  ["Show the focus frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "إظهار إطار التركيز في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هو مخفي الآن.",
  ["Show the focus target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "إظهار إطار هدف التركيز في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هو مخفي الآن.",
  ["Show the gap to the nearest element on each side of the selected one."] = "إظهار المسافة إلى أقرب عنصر على كل جانب من العنصر المحدد.",
  ["Show the party frames everywhere, never, or only in the content, combat state and group you pick. The line below explains why they are hidden right now."] = "إظهار إطارات المجموعة في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هي مخفية الآن.",
  ["Show the pet frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "إظهار إطار الرفيق في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هو مخفي الآن.",
  ["Show the player frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "إظهار إطار اللاعب في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هو مخفي الآن.",
  ["Show the raid frames everywhere, never, or only in the content, combat state and group you pick. The line below explains why they are hidden right now."] = "إظهار إطارات الغارة في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هي مخفية الآن.",
  ["Show the rated card"] = "إظهار البطاقة المصنفة",
  ["Show the ring only while you are in combat."] = "إظهار الحلقة أثناء القتال فقط.",
  ["Show the target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "إظهار إطار الهدف في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هو مخفي الآن.",
  ["Show the target of target frame everywhere, never, or only in the content, combat state and group you pick. The line below explains why it is hidden right now."] = "إظهار إطار هدف الهدف في كل مكان، أو أبدًا، أو فقط في المحتوى وحالة القتال والمجموعة التي تختارها. السطر أدناه يشرح لماذا هو مخفي الآن.",
