  ["Shows an NPC's title, such as <Innkeeper> or <Flight Master>, under its name."] = "يعرض لقب الشخصية غير اللاعبة، مثل <صاحب النزل> أو <مدير الطيران>، تحت اسمها.",
  ["Shows auras you gain in Spark."] = "يعرض التأثيرات التي تكتسبها في Spark.",
  ["Shows auras you lose in Spark."] = "يعرض التأثيرات التي تفقدها في Spark.",
