  ["Shows casts and channels under enemy plates, with the shield for casts you cannot interrupt."] = "يعرض الإلقاءات والتوجيهات تحت لوحات الأعداء، مع الدرع للإلقاءات التي لا يمكنك مقاطعتها.",
  ["Shows currency in Spark."] = "يعرض العملات في Spark.",
