  ["Shows entering combat in Spark."] = "يعرض دخول القتال في Spark.",
  ["Shows experience in Spark."] = "يعرض الخبرة في Spark.",
  ["Shows heals you get in Spark."] = "يعرض الشفاء الذي تتلقاه في Spark.",
  ["Shows heals your pet gets in Spark."] = "يعرض الشفاء الذي يتلقاه رفيقك في Spark.",
  ["Shows hits you avoid (dodge, parry, absorb...) in Spark."] = "يعرض الضربات التي تتفاداها (المراوغة، الصد، الامتصاص...) في Spark.",
  ["Shows honor in Spark."] = "يعرض الشرف في Spark.",
  ["Shows how many bosses a raid group has already killed and adds the filter word bossesdown. Uses a game function Blizzard's own list uses; it turns off by itself if a patch removes it."] = "يعرض عدد الزعماء الذين قتلتهم مجموعة الغارة ويضيف كلمة المرشح bossesdown. يستخدم دالة لعبة تستخدمها قائمة Blizzard نفسها؛ يتوقف تلقائيًا إذا أزالها تحديث.",
  ["Shows how many minutes ago the group was listed."] = "يعرض منذ كم دقيقة أُدرجت المجموعة.",
  ["Shows interrupt counts for your group (from the Embers meter data)."] = "يعرض أعداد المقاطعات لمجموعتك (من بيانات عدّاد Embers).",
  ["Shows item or potion ready in Spark."] = "يعرض جاهزية الغرض أو الجرعة في Spark.",
