  ["Shows loot in Spark."] = "يعرض الغنائم في Spark.",
  ["Shows macro names on action buttons."] = "يعرض أسماء الماكرو على أزرار الأوامر.",
  ["Shows money in Spark."] = "يعرض المال في Spark.",
  ["Shows only the button, without the decorative frame around it."] = "يعرض الزر فقط، دون الإطار الزخرفي حوله.",
  ["Shows only the zone ability button, without its frame."] = "يعرض زر قدرة المنطقة فقط، دون إطاره.",
  ["Shows predicted incoming heals after the health fill."] = "يعرض الشفاء الوارد المتوقع بعد تعبئة الصحة.",
  ["Shows raid buffs someone in your group can give that you are missing."] = "يعرض تعزيزات الغارة التي يستطيع أحد في مجموعتك منحها وتنقصك.",
  ["Shows raid target markers above plates."] = "يعرض علامات أهداف الغارة فوق اللوحات.",
  ["Shows reputation in Spark."] = "يعرض السمعة في Spark.",
  ["Shows shared battle-res charges and whether you can get Bloodlust again."] = "يعرض شحنات الإحياء القتالي المشتركة وما إذا كان بإمكانك الحصول على التعطش للدماء مجددًا.",
  ["Shows skill ups in Spark."] = "يعرض ارتفاع المهارات في Spark.",
  ["Shows the DR tray only on enemy healers."] = "يعرض صينية تناقص المفعول على معالجي الأعداء فقط.",
  ["Shows the Phoenix UI button on the minimap edge. Left-click opens options, right-click opens Studio, Shift-click opens Sentinel, drag to move."] = "يعرض زر Phoenix UI على حافة الخريطة المصغرة. النقر الأيسر يفتح الخيارات، والأيمن يفتح Studio، وShift+نقر يفتح Sentinel، والسحب يحرّكه.",
  ["Shows the PvP flag icon on unit frames."] = "يعرض أيقونة علم PvP على إطارات الوحدات.",
  ["Shows the ability icon beside each bar."] = "يعرض أيقونة القدرة بجوار كل شريط.",
  ["Shows the achievement ID on tooltips."] = "يعرض معرّف الإنجاز في التلميحات.",
  ["Shows the area poi ID on tooltips."] = "يعرض معرّف نقطة اهتمام المنطقة في التلميحات.",
