  ["Shows the battle pet species ID on tooltips."] = "يعرض معرّف فصيلة رفيق المعارك في التلميحات.",
  ["Shows the bonus ID on tooltips. Off by default because it is long or rarely needed."] = "يعرض معرّف المكافأة في التلميحات. متوقف افتراضيًا لأنه طويل ونادرًا ما يُحتاج.",
  ["Shows the bound key on each action button."] = "يعرض المفتاح المربوط على كل زر أوامر.",
  ["Shows the buffs from your own list below when they are missing."] = "يعرض التعزيزات من قائمتك أدناه عندما تكون مفقودة.",
  ["Shows the cast bar in the resource stack."] = "يعرض شريط الإلقاء في كومة الموارد.",
  ["Shows the cast bar only on enemy healers."] = "يعرض شريط الإلقاء على معالجي الأعداء فقط.",
  ["Shows the class resource in the resource stack."] = "يعرض موارد الفئة في كومة الموارد.",
