  ["Shows the dungeon score a timed run of this key would give against your best (an estimate)."] = "يعرض نقاط الزنزانة التي ستمنحها جولة ضمن الوقت لهذا المفتاح مقارنة بأفضل نتيجة لك (تقدير).",
  ["Shows the elite / rare icon on unit frames."] = "يعرض أيقونة النخبة / النادر على إطارات الوحدات.",
