  ["Shows the kicks column on the run summary card."] = "يعرض عمود المقاطعات على بطاقة ملخص الجولة.",
  ["Shows the leader's Mythic+ score in the colour source you picked (Blizzard, Raider.IO or your own gradient)."] = "يعرض نقاط الأسطوري+ للقائد بمصدر اللون الذي اخترته (Blizzard أو Raider.IO أو تدرجك الخاص).",
  ["Shows the leader's realm language ([DE], [FR] ...) when an addon with LibRealmInfo is loaded."] = "يعرض لغة عالم القائد ‏([DE]، [FR] ...) عند تحميل ملحق يحتوي على LibRealmInfo.",
  ["Shows the macro ID on tooltips."] = "يعرض معرّف الماكرو في التلميحات.",
  ["Shows the mount ID on tooltips."] = "يعرض معرّف المطية في التلميحات.",
