  ["Shows the outgoing scroll area."] = "يعرض منطقة النص الصادر.",
  ["Shows the pet ability ID on tooltips."] = "يعرض معرّف قدرة الرفيق في التلميحات.",
  ["Shows the power bar in the resource stack."] = "يعرض شريط الطاقة في كومة الموارد.",
  ["Shows the quest ID on tooltips."] = "يعرض معرّف المهمة في التلميحات.",
