  ["Shows the shared combat and encounter timer in the title."] = "يعرض مؤقت القتال والمواجهة المشترك في العنوان.",
  ["Shows the spell ID on tooltips."] = "يعرض معرّف التعويذة في التلميحات.",
  ["Shows the spell icon beside the cast bar."] = "يعرض أيقونة التعويذة بجوار شريط الإلقاء.",
