  ["Shows the spell name on the cast bar."] = "يعرض اسم التعويذة على شريط الإلقاء.",
  ["Shows the spell or item icon beside a line."] = "يعرض أيقونة التعويذة أو الغرض بجوار السطر.",
  ["Shows the spell or item tooltip when the pointer is over an action button."] = "يعرض تلميح التعويذة أو الغرض عندما يكون المؤشر فوق زر أوامر.",
  ["Shows the spell tooltip when you point at an icon."] = "يعرض تلميح التعويذة عند الإشارة إلى أيقونة.",
