  ["Shows the talent ID on tooltips."] = "يعرض معرّف الموهبة في التلميحات.",
  ["Shows the time left as numbers on each cooldown icon (the game's own countdown)."] = "يعرض الوقت المتبقي أرقامًا على كل أيقونة فترة تهدئة (العد التنازلي الخاص باللعبة).",
  ["Shows the time left on a cooldown as numbers on the button (drawn by the game's own countdown)."] = "يعرض الوقت المتبقي لفترة التهدئة أرقامًا على الزر (يرسمه العد التنازلي الخاص باللعبة).",
  ["Shows the time left on the cast bar."] = "يعرض الوقت المتبقي على شريط الإلقاء.",
  ["Shows the time left on the invite under the Enter button. The time comes from the shared queue timer (also used by the minimap eye); set the dungeon invite length with 'Dungeon queue-pop time'."] = "يعرض الوقت المتبقي للدعوة تحت زر الدخول. يأتي الوقت من مؤقت الطابور المشترك (تستخدمه عين الخريطة المصغرة أيضًا)؛ اضبط مدة دعوة الزنزانة عبر «وقت ظهور طابور الزنزانة».",
  ["Shows the time on the minimap."] = "يعرض الوقت على الخريطة المصغرة.",
  ["Shows the title bar with meter, fight and timer."] = "يعرض شريط العنوان مع العدّاد والقتال والمؤقت.",
  ["Shows the totem bars in the resource stack."] = "يعرض أشرطة الطواطم في كومة الموارد.",
  ["Shows the trait definition ID on tooltips. Off by default because it is long or rarely needed."] = "يعرض معرّف تعريف السمة في التلميحات. متوقف افتراضيًا لأنه طويل ونادرًا ما يُحتاج.",
  ["Shows the trait entry ID on tooltips. Off by default because it is long or rarely needed."] = "يعرض معرّف مدخل السمة في التلميحات. متوقف افتراضيًا لأنه طويل ونادرًا ما يُحتاج.",
  ["Shows the trait node ID on tooltips. Off by default because it is long or rarely needed."] = "يعرض معرّف عقدة السمة في التلميحات. متوقف افتراضيًا لأنه طويل ونادرًا ما يُحتاج.",
  ["Shows the transmog source ID on tooltips."] = "يعرض معرّف مصدر تحويل المظهر في التلميحات.",
  ["Shows the transmog visual ID on tooltips."] = "يعرض معرّف مرئية تحويل المظهر في التلميحات.",
  ["Shows the trinket only on enemy healers (needs their spec, known from the preparation phase)."] = "يعرض الحلية على معالجي الأعداء فقط (يحتاج تخصصهم، المعروف من مرحلة التحضير).",
  ["Shows the unit's name on enemy plates."] = "يعرض اسم الوحدة على لوحات الأعداء.",
  ["Shows the vignette ID on tooltips."] = "يعرض معرّف المعلم في التلميحات.",
  ["Shows the zone name on the minimap."] = "يعرض اسم المنطقة على الخريطة المصغرة.",
  ["Shows whether your current role still fits the group."] = "يعرض ما إذا كان دورك الحالي لا يزال يناسب المجموعة.",
  ["Shows whether your enemy forces are ahead of or behind an even pace for +1, +2 and +3."] = "يعرض ما إذا كانت قوات الأعداء لديك متقدمة على الوتيرة المتساوية لـ +1 و+2 و+3 أو متأخرة عنها.",
  ["Shows which roles the group still needs."] = "يعرض الأدوار التي لا تزال المجموعة تحتاجها.",
  ["Shows who pinged the minimap for a few seconds."] = "يعرض لبضع ثوانٍ من أرسل تنبيهًا على الخريطة المصغرة.",
  ["Shows your /way waypoint at the top; click it to clear."] = "يعرض نقطة الطريق /way في الأعلى؛ انقرها لمسحها.",
  ["Shows your combo points, holy power, chi and similar under your target's plate. Needs the Resource Bars add-on loaded (it does not have to be switched on)."] = "يعرض نقاط الكومبو والقوة المقدسة والتشي وما شابه تحت لوحة هدفك. يحتاج ملحق أشرطة الموارد محمّلًا (لا يلزم تفعيله).",
  ["Shows your damage in Spark."] = "يعرض ضررك في Spark.",
  ["Shows your frame even when you are not in a group."] = "يعرض إطارك حتى عندما لا تكون في مجموعة.",
  ["Shows your heals in Spark."] = "يعرض شفاءك في Spark.",
  ["Shows your interrupt and its cooldown beside the cast bar."] = "يعرض مقاطعتك وفترة تهدئتها بجوار شريط الإلقاء.",
  ["Shows your interrupt and its cooldown next to each cast, so you see at a glance whether your kick is ready."] = "يعرض مقاطعتك وفترة تهدئتها بجوار كل إلقاء، لترى بنظرة إن كانت جاهزة.",
  ["Shows your misses in Spark."] = "يعرض ضرباتك الضائعة في Spark.",
  ["Shows your notes for your target or the last boss, only out of combat. Move it in Studio."] = "يعرض ملاحظاتك لهدفك أو آخر زعيم، خارج القتال فقط. حرّكها في Studio.",
  ["Shows your own class buffs that are missing, like rogue poisons or a paladin aura."] = "يعرض تعزيزات فئتك المفقودة، مثل سموم المحتال أو هالة الفارس المقدس.",
  ["Shows your quest progress for an enemy, such as \"Void Acolytes slain: 3/8\", under its name."] = "يعرض تقدم مهمتك على عدو، مثل «مريدو الفراغ المقتولون: 3/8»، تحت اسمه.",
  ["Shows your rating change on the card."] = "يعرض تغير تصنيفك على البطاقة.",
  ["Shows your triggers in Spark."] = "يعرض مشغّلاتك في Spark.",
  ["Shrinks the role bar to its + button."] = "يقلّص شريط الأدوار إلى زر +.",
  ["Side of the frame the icons sit on."] = "جانب الإطار الذي تقع عليه الأيقونات.",
  ["Sideways distance from the cursor for the left/right cursor positions."] = "المسافة الجانبية من المؤشر لمواضع يسار/يمين المؤشر.",
  ["SimC export"] = "تصدير SimC",
  ["SimC export includes bag gear"] = "تصدير SimC يشمل معدات الحقائب",
  ["Simple shows the curated settings; Advanced shows every setting."] = "البسيط يعرض الإعدادات المختارة؛ المتقدم يعرض كل إعداد.",
  ["Six hex digits, e.g. 8a8a8a."] = "ست خانات ست عشرية، مثلًا 8a8a8a.",
