  ["Solo Shuffle round results"] = "نتائج جولات Solo Shuffle",
  ["Solo Shuffle round tracker"] = "متتبع جولات Solo Shuffle",
  ["Some changes cannot happen in combat. A short notice at the top of the screen says so, and the change happens when combat ends."] = "بعض التغييرات لا يمكن أن تحدث أثناء القتال. يذكر ذلك إشعار قصير أعلى الشاشة، ويحدث التغيير عند انتهاء القتال.",
  ["Sort"] = "الفرز",
