  ["Sort quests by"] = "فرز المهام حسب",
  ["Sort right to left"] = "الفرز من اليمين إلى اليسار",
  ["Sort scoreboard by"] = "فرز لوحة النتائج حسب",
  ["Soul fragments"] = "شظايا الروح",
