  ["Sound channel for aura sounds (Master plays even with effects muted)."] = "قناة الصوت لأصوات التأثيرات (الرئيسية تعمل حتى مع كتم المؤثرات).",
  ["Sound for Phoenix alerts (reminders, group finder, quest complete). None keeps each module's own sound."] = "صوت تنبيهات Phoenix (التذكيرات، أداة البحث عن مجموعة، إكمال المهمة). «بلا» يبقي صوت كل وحدة الخاص.",
  ["Sound for the threat warning (None uses the raid warning sound)."] = "صوت تحذير التهديد («بلا» يستخدم صوت تحذير الغارة).",
  ["Sound on a new error"] = "صوت عند خطأ جديد",
  ["Sound played once when the invite is about to expire."] = "صوت يُشغّل مرة واحدة عندما توشك الدعوة على الانتهاء.",
  ["Sound when ready"] = "صوت عند الجاهزية",
  ["Sound when the countdown starts"] = "صوت عند بدء العد التنازلي",
  ["Space between bars"] = "المسافة بين الأشرطة",
  ["Space between docked Blizzard meter windows."] = "المسافة بين نوافذ عدّاد Blizzard المرصوفة.",
  ["Space between docked windows."] = "المسافة بين النوافذ المرصوفة.",
  ["Space between frames"] = "المسافة بين الإطارات",
  ["Space between groups (columns or rows)."] = "المسافة بين المجموعات (الأعمدة أو الصفوف).",
