  ["Space between rows."] = "المسافة بين الصفوف.",
  ["Space between slots."] = "المسافة بين الخانات.",
  ["Space between stacked plates; 0 keeps the game's value."] = "المسافة بين اللوحات المكدسة؛ 0 يبقي قيمة اللعبة.",
  ["Space between the player frame and the attached resource bars."] = "المسافة بين إطار اللاعب وأشرطة الموارد الملحقة.",
  ["Space between the text and the panel edge."] = "المسافة بين النص وحافة اللوحة.",
  ["Spacing"] = "التباعد",
  ["Spacing of the Studio pixel grid, in UI pixels."] = "تباعد شبكة بكسلات Studio، ببكسلات الواجهة.",
  ["Spark"] = "Spark",
