  ["Spark: Outgoing"] = "Spark: الصادر",
  ["Spark: Static (sticky)"] = "Spark: الثابت (اللاصق)",
  ["Spec icon"] = "أيقونة التخصص",
  ["Spec icon next to each row."] = "أيقونة التخصص بجوار كل صف.",
  ["Spec icon side"] = "جانب أيقونة التخصص",
  ["Spec, talent loadout and gear set per kind of content, checked when you zone in."] = "التخصص وحزمة المواهب وطقم المعدات لكل نوع محتوى، تُفحص عند دخول المنطقة.",
  ["Specialization 1 (Arcane)"] = "التخصص 1 (الغموض)",
  ["Specialization 2 (Arcane)"] = "التخصص 2 (الغموض)",
  ["Specialization 3 (Arcane)"] = "التخصص 3 (الغموض)",
  ["Specialization 4 (Arcane)"] = "التخصص 4 (الغموض)",
  ["Speed of every scroll area."] = "سرعة كل منطقة تمرير.",
  ["Spell ID of your aura; its stacks fill the bar."] = "معرّف تعويذة تأثيرك؛ تكدساته تملأ الشريط.",
  ["Spell IDs left out of the Phoenix rows, comma-separated. /pui cdmspells lists the tracked spells with their IDs."] = "معرّفات التعاويذ المستبعدة من صفوف Phoenix، مفصولة بفواصل. الأمر /pui cdmspells يسرد التعاويذ المتتبعة مع معرّفاتها.",
  ["Spell IDs never shown. Ctrl+Alt+click an icon to add it; the picker lists every spell matching a name."] = "معرّفات تعاويذ لا تُعرض أبدًا. Ctrl+Alt+نقر على أيقونة يضيفها؛ أداة الاختيار تسرد كل تعويذة تطابق اسمًا.",
  ["Spell IDs that keep full colour even when the game marks them unusable (for example Swiftmend, usable only on a target with your heal over time)."] = "معرّفات تعاويذ تحتفظ بلونها الكامل حتى عندما تعلّمها اللعبة غير قابلة للاستخدام (مثل الإصلاح السريع، القابل للاستخدام فقط على هدف عليه شفاؤك المستمر).",
  ["Spell IDs that may glow, comma-separated. Empty means every tracked cooldown."] = "معرّفات التعاويذ التي يمكن أن تتوهج، مفصولة بفواصل. الفارغ يعني كل فترة تهدئة متتبعة.",
  ["Spell IDs that play your alert sound when their cooldown finishes, comma-separated."] = "معرّفات التعاويذ التي تشغّل صوت تنبيهك عند انتهاء فترة تهدئتها، مفصولة بفواصل.",
  ["Spell alerts"] = "تنبيهات التعاويذ",
  ["Spell blocklist"] = "قائمة حظر التعاويذ",
  ["Spell flyouts (portals, pets, totems) use the same icon crop and border as your bars."] = "القوائم المنبثقة للتعاويذ (البوابات، الرفقاء، الطواطم) تستخدم قص الأيقونة والحد نفسيهما كأشرطتك.",
  ["Spell icon"] = "أيقونة التعويذة",
  ["Spell icon beside the cast bar."] = "أيقونة التعويذة بجوار شريط الإلقاء.",
  ["Spell icons"] = "أيقونات التعاويذ",
  ["Spell name"] = "اسم التعويذة",
  ["Spell name on the cast bar."] = "اسم التعويذة على شريط الإلقاء.",
  ["Spell name size"] = "حجم اسم التعويذة",
  ["Spell ranks (Forever)"] = "رتب التعاويذ (Forever)",
  ["Spell used to check range. Empty uses a ranged spell of your class."] = "التعويذة المستخدمة لفحص المدى. الفارغ يستخدم تعويذة بعيدة المدى من فئتك.",
  ["Spellbook and talents"] = "كتاب التعاويذ والمواهب",
  ["Spells label colour"] = "لون تسمية التعاويذ",
  ["Spells you want to see as small squares in a corner, one per line as CORNER:spellID, then optionally :mine or :any and a colour (RRGGBB). Example: TOPLEFT:774:mine. Use the preset button for your class's heals. In some restricted fights the game hides other players' auras; then a square stays off."] = "التعاويذ التي تريد رؤيتها مربعات صغيرة في زاوية، واحدة في كل سطر بصيغة CORNER:spellID، ثم اختياريًا :mine أو :any ولون (RRGGBB). مثال: TOPLEFT:774:mine. استخدم زر الإعداد المسبق لشفاء فئتك. في بعض المعارك المقيدة تخفي اللعبة تأثيرات اللاعبين الآخرين؛ عندها يبقى المربع مطفأ.",
  ["Spells: Artifact power ID"] = "التعاويذ: معرّف قوة القطعة الأثرية",
  ["Spells: Follower ability ID"] = "التعاويذ: معرّف قدرة التابع",
  ["Spells: Macro ID"] = "التعاويذ: معرّف الماكرو",
  ["Spells: Pet ability ID"] = "التعاويذ: معرّف قدرة الرفيق",
  ["Spells: Spell ID"] = "التعاويذ: معرّف التعويذة",
  ["Spells: Talent ID"] = "التعاويذ: معرّف الموهبة",
  ["Spells: Trait definition ID"] = "التعاويذ: معرّف تعريف السمة",
