  ["Tell me what is missing from my bars"] = "أخبرني بما ينقص أشرطتي",
  ["Tells you in chat when your spec, talents or gear do not match the loadout for where you are."] = "يخبرك في الدردشة عندما لا يطابق تخصصك أو مواهبك أو معداتك الحزمة الخاصة بمكانك.",
