  ["Text colour."] = "لون النص.",
  ["Text font"] = "خط النص",
  ["Text on the health bar."] = "النص على شريط الصحة.",
  ["Text on the power bar."] = "النص على شريط الطاقة.",
  ["Text on the progress bar."] = "النص على شريط التقدم.",
  ["Text outline"] = "حد النص",
  ["Text shadow"] = "ظل النص",
  ["Text size"] = "حجم النص",
  ["Texture for every Phoenix health, power, cast and resource bar."] = "خامة كل أشرطة الصحة والطاقة والإلقاء والموارد في Phoenix.",
  ["Texture of the tracked buff bars."] = "خامة أشرطة التعزيزات المتتبعة.",
  ["The All tab also searches players you grouped with recently."] = "تبويب «الكل» يبحث أيضًا في اللاعبين الذين جمعتك بهم مجموعة مؤخرًا.",
  ["The All tab also searches your guild."] = "تبويب «الكل» يبحث أيضًا في نقابتك.",
  ["The PvP trinket shows the Horde or Alliance medal."] = "تعرض حلية PvP وسام الحشد أو التحالف.",
  ["The action page bar 1 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 1 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 10 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 10 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 2 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 2 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 3 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 3 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 4 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 4 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 5 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 5 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 6 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 6 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 7 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 7 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 8 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 8 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The action page bar 9 shows while its paging modifier is held."] = "تظهر صفحة أوامر الشريط 9 أثناء الضغط على مفتاح تعديل التقليب.",
  ["The bar stays invisible until you point at it."] = "يبقى الشريط غير مرئي حتى تشير إليه.",
  ["The bar turns red when this many seconds are left."] = "يتحول الشريط إلى الأحمر عند بقاء هذا العدد من الثواني.",
  ["The border and backdrop style of every plate. Each part below can still be changed on its own."] = "نمط الحد والخلفية لكل لوحة. لا يزال بالإمكان تغيير كل جزء أدناه منفردًا.",
  ["The border around every Phoenix window, frame and icon outline."] = "الحد حول كل نافذة وإطار وحد أيقونة في Phoenix.",
  ["The clock block uses 24-hour time."] = "كتلة الساعة تستخدم نظام 24 ساعة.",
  ["The countdown bar turns red with this many seconds left."] = "يتحول شريط العد التنازلي إلى الأحمر عند بقاء هذا العدد من الثواني.",
  ["The docked bar fades to this while the mouse is away; 1 never fades."] = "يتلاشى الشريط المرصوف إلى هذه القيمة أثناء ابتعاد الفأرة؛ 1 لا يتلاشى أبدًا.",
  ["The dungeon ready pop-up ignores clicks for a moment so a stray click cannot accept or leave."] = "تتجاهل نافذة جاهزية الزنزانة النقرات للحظة حتى لا تقبل نقرة طائشة أو تغادر.",
  ["The enemy's racial ability. Racials that share a cooldown with the trinket lock when the trinket is used."] = "القدرة العرقية للعدو. القدرات العرقية التي تشارك فترة التهدئة مع الحلية تُقفل عند استخدام الحلية.",
  ["The enemy's spec icon, shown from the preparation room on."] = "أيقونة تخصص العدو، تظهر بدءًا من غرفة التحضير.",
  ["The enemy's trinket with its cooldown, from the game's own data."] = "حلية العدو مع فترة تهدئتها، من بيانات اللعبة نفسها.",
  ["The first time Phoenix bars turn on, each bar starts where your Edit Mode layout had it. Bars you already moved are kept. /pui abcapture copies them again."] = "عند تفعيل أشرطة Phoenix لأول مرة، يبدأ كل شريط حيث كان في تخطيط وضع التحرير. الأشرطة التي نقلتها تُحفظ. الأمر /pui abcapture ينسخها مجددًا.",
  ["The frame around every button. Each part (border, zoom, fonts) can still be changed on its own."] = "الإطار حول كل زر. لا يزال بالإمكان تغيير كل جزء (الحد، التقريب، الخطوط) منفردًا.",
  ["The game's nameplate scale; 0 keeps the game's value."] = "مقياس لوحات الأسماء في اللعبة؛ 0 يبقي قيمة اللعبة.",
  ["The game's own target plate scale; 0 keeps the game's value. Phoenix's target size above works on top of it."] = "مقياس لوحة الهدف الخاص باللعبة؛ 0 يبقي قيمة اللعبة. حجم الهدف في Phoenix أعلاه يعمل فوقه.",
  ["The header, background and border fade out and come back while your mouse is over the window; the rows stay."] = "يتلاشى العنوان والخلفية والحد ويعودون أثناء وجود الفأرة فوق النافذة؛ الصفوف تبقى.",
  ["The header, dropdowns and backdrop of Blizzard's meter windows fade out and come back while the mouse is over them."] = "يتلاشى عنوان نوافذ عدّاد Blizzard وقوائمها المنسدلة وخلفيتها وتعود أثناء وجود الفأرة فوقها.",
  ["The health bar under unit tooltips."] = "شريط الصحة تحت تلميحات الوحدات.",
  ["The item bar stays faded until you point at it."] = "يبقى شريط الأغراض متلاشيًا حتى تشير إليه.",
  ["The latest cast glows."] = "يتوهج آخر إلقاء.",
  ["The line cap for this area in big pulls."] = "حد الأسطر لهذه المنطقة في السحبات الكبيرة.",
  ["The look of the button on the minimap that opens the bin."] = "مظهر الزر على الخريطة المصغرة الذي يفتح الحاوية.",
  ["The meter type and fight dropdowns in the header get the Phoenix look."] = "القائمتان المنسدلتان لنوع العدّاد والقتال في العنوان تأخذان مظهر Phoenix.",
  ["The mouse wheel scrolls through everyone in the fight; there is no scroll bar."] = "عجلة الفأرة تمرر عبر كل من في القتال؛ لا يوجد شريط تمرير.",
  ["The pet bar stays faded until you point at it."] = "يبقى شريط الرفيق متلاشيًا حتى تشير إليه.",
  ["The popup closes after the delay below once the mouse leaves it."] = "تُغلق النافذة المنبثقة بعد التأخير أدناه بمجرد خروج الفأرة منها.",
  ["The popup closes and the bar hides when combat starts; the bar comes back after combat."] = "تُغلق النافذة المنبثقة ويختفي الشريط عند بدء القتال؛ يعود الشريط بعد القتال.",
  ["The profile this specialization uses. No change keeps whatever profile is active."] = "الملف الشخصي الذي يستخدمه هذا التخصص. «بلا تغيير» يبقي أي ملف نشط.",
  ["The raid layout used for every raid size when automatic picking is off."] = "تخطيط الغارة المستخدم لكل أحجام الغارة عند إيقاف الاختيار التلقائي.",
  ["The same error alerts at most once in this many seconds (it is always counted)."] = "الخطأ نفسه ينبّه مرة واحدة على الأكثر كل هذا العدد من الثواني (يُحسب دائمًا).",
  ["The scoreboard stays open after you leave the battleground."] = "تبقى لوحة النتائج مفتوحة بعد مغادرة ساحة المعركة.",
  ["The shared Phoenix cast bar under each enemy, with your kick state."] = "شريط إلقاء Phoenix المشترك تحت كل عدو، مع حالة مقاطعتك.",
  ["The single highlight colour of Phoenix UI. Class uses your class colour."] = "لون التمييز الوحيد في Phoenix UI. «الفئة» يستخدم لون فئتك.",
  ["The spec icon shows the enemy's most important aura while it lasts (crowd control, big defensive or important, in your order)."] = "تعرض أيقونة التخصص أهم تأثير على العدو طوال مدته (السيطرة، دفاعي كبير أو مهم، بترتيبك).",
  ["The spell whose range is checked. 0 uses your interrupt."] = "التعويذة التي يُفحص مداها. 0 يستخدم مقاطعتك.",
  ["The stance bar stays faded until you point at it."] = "يبقى شريط الوضعيات متلاشيًا حتى تشير إليه.",
  ["The strip stops moving while you point at it."] = "يتوقف الشريط عن الحركة أثناء إشارتك إليه.",
  ["The vehicle exit button stays faded until you point at it."] = "يبقى زر الخروج من المركبة متلاشيًا حتى تشير إليه.",
  ["Theme"] = "السمة",
  ["Theme accent or your class colour."] = "لون تمييز السمة أو لون فئتك.",
  ["There is no combat log in Midnight: Spark works out your hits from your own casts."] = "لا يوجد سجل قتال في Midnight: يستنتج Spark ضرباتك من إلقاءاتك.",
  ["Thick or thin ring."] = "حلقة سميكة أو رفيعة.",
  ["Thickness of pixel-line borders (0 hides them)."] = "سماكة حدود خطوط البكسل (0 يخفيها).",
  ["Thin Phoenix scroll bars in every skinned window."] = "أشرطة تمرير Phoenix رفيعة في كل نافذة منسقة.",
  ["Thin accent border around each window."] = "حد رفيع بلون التمييز حول كل نافذة.",
  ["Thin accent border around the panel."] = "حد رفيع بلون التمييز حول اللوحة.",
  ["Thin lines between blocks."] = "خطوط رفيعة بين الكتل.",
  ["Thin rail with an accent thumb."] = "مسار رفيع بمقبض بلون التمييز.",
  ["Thin scroll marker"] = "علامة تمرير رفيعة",
  ["This week's wins and losses, conquest earned and the PvP row of the Great Vault on one line."] = "انتصارات هذا الأسبوع وهزائمه والغزو المكتسب وصف PvP في الخزنة العظمى في سطر واحد.",
  ["Threat colour style"] = "نمط ألوان التهديد",
  ["Threat colours"] = "ألوان التهديد",
  ["Threat glow"] = "توهج التهديد",
  ["Threat warning at (%)"] = "تحذير التهديد عند (%)",
  ["Threat warning sound"] = "صوت تحذير التهديد",
  ["Threat: as wanted"] = "التهديد: كما يجب",
  ["Threat: changing"] = "التهديد: يتغير",
  ["Threat: wrong"] = "التهديد: خاطئ",
  ["Threshold sounds"] = "أصوات العتبات",
  ["Tick a box to show health bars for that kind of friendly unit in that content. Unticked shows the name only (the default everywhere). Inside instances the game may keep friendly plates for itself; then its own plate shows."] = "حدّد مربعًا لإظهار أشرطة الصحة لذلك النوع من الوحدات الصديقة في ذلك المحتوى. غير المحدد يعرض الاسم فقط (الافتراضي في كل مكان). داخل المثيلات قد تحتفظ اللعبة باللوحات الصديقة لنفسها؛ عندها تظهر لوحتها.",
  ["Tick a topic for the content types where it may be announced. Everything starts unticked."] = "حدّد موضوعًا لأنواع المحتوى التي يمكن الإعلان عنه فيها. كل شيء يبدأ غير محدد.",
  ["Tick an option for the content types where it should apply. Everything starts unticked; sound options return to your own values when they stop applying."] = "حدّد خيارًا لأنواع المحتوى التي يجب أن يُطبّق فيها. كل شيء يبدأ غير محدد؛ خيارات الصوت تعود إلى قيمك عندما تتوقف عن التطبيق.",
  ["Tick marks for your channels: spell ID = number of ticks, comma-separated, e.g. 15407=6, 5143=5."] = "علامات النبضات للتوجيهات: معرّف التعويذة = عدد النبضات، مفصولة بفواصل، مثلًا 15407=6, 5143=5.",
  ["Tick marks on the timer bar where +3 and +2 run out."] = "علامات على شريط المؤقت حيث ينتهي وقت +3 و+2.",
  ["Ticket status"] = "حالة التذكرة",
  ["Time format"] = "تنسيق الوقت",
  ["Time in front of each line. Lines the game keeps secret in restricted content are shown unchanged."] = "الوقت أمام كل سطر. الأسطر التي تخفيها اللعبة في المحتوى المقيد تُعرض دون تغيير.",
  ["Time left on the cast bar."] = "الوقت المتبقي على شريط الإلقاء.",
  ["Timer colour inside the refresh window."] = "لون المؤقت داخل نافذة التجديد.",
  ["Timer format"] = "تنسيق المؤقت",
  ["Timer shows in"] = "يظهر المؤقت في",
  ["Timer text size"] = "حجم نص المؤقت",
  ["Times Phoenix's registered entry points and Ticker jobs (/pui profile). Off costs nothing: no wrappers exist while it is off."] = "يقيس زمن نقاط الدخول المسجلة ومهام Ticker في Phoenix ‏(/pui profile). الإيقاف لا يكلف شيئًا: لا توجد أغلفة أثناء الإيقاف.",
  ["Timestamp colour (hex)"] = "لون الطابع الزمني (hex)",
  ["Timestamps"] = "الطوابع الزمنية",
  ["Timestamps become links that open the line in the copy box."] = "تصبح الطوابع الزمنية روابط تفتح السطر في مربع النسخ.",
  ["Tint of buttons you cannot use right now."] = "صبغة الأزرار التي لا يمكنك استخدامها الآن.",
  ["Tint of buttons you lack the mana, energy or other power for."] = "صبغة الأزرار التي تنقصك لها المانا أو الطاقة أو قوة أخرى.",
  ["Title bar"] = "شريط العنوان",
  ["Toast style"] = "نمط الإشعارات",
  ["Tooltip"] = "التلميح",
  ["Tooltip IDs"] = "معرّفات التلميحات",
  ["Tooltip anchor"] = "مرساة التلميح",
  ["Tooltip background opacity"] = "عتامة خلفية التلميح",
  ["Tooltip on hover"] = "تلميح عند التمرير",
  ["Tooltip position"] = "موضع التلميح",
  ["Tooltip position, style, info lines and IDs (28 kinds, click-free copy)."] = "موضع التلميح ونمطه وأسطر المعلومات والمعرّفات (28 نوعًا، نسخ دون نقر).",
  ["Tooltip scale"] = "حجم التلميح",
  ["Tooltips in combat"] = "التلميحات أثناء القتال",
  ["Top centre container"] = "حاوية أعلى الوسط",
  ["Top centre widgets"] = "أدوات أعلى الوسط",
  ["Totem and pet plates show only their bar."] = "لوحات الطواطم والرفقاء تعرض شريطها فقط.",
  ["Totem bars"] = "أشرطة الطواطم",
  ["Totem bars height"] = "ارتفاع أشرطة الطواطم",
  ["Totems"] = "الطواطم",
  ["Totems get a smaller plate so they never crowd real enemies."] = "تحصل الطواطم على لوحة أصغر حتى لا تزاحم الأعداء الحقيقيين.",
  ["Track zone quests"] = "تتبع مهام المنطقة",
  ["Tracked buff bars"] = "أشرطة التعزيزات المتتبعة",
  ["Tracked buff icons"] = "أيقونات التعزيزات المتتبعة",
  ["Tracker width."] = "عرض المتتبع.",
  ["Tracking, calendar and mail buttons"] = "أزرار التتبع والتقويم والبريد",
  ["Tracks quests for the zone you enter."] = "يتتبع مهام المنطقة التي تدخلها.",
  ["Trade"] = "المقايضة",
  ["Train All button"] = "زر تعلّم الكل",
  ["Trainer"] = "المدرّب",
  ["Training Grounds buttons"] = "أزرار ساحات التدريب",
  ["Trait trees (Delves, Skyriding)"] = "أشجار السمات (الأغوار، الطيران الحر)",
  ["Transmog"] = "تحويل المظهر",
  ["Trigger list"] = "قائمة المشغّلات",
  ["Triggers"] = "المشغّلات",
  ["Trims the icon edges."] = "يقص حواف الأيقونة.",
  ["Trinket and racial size"] = "حجم الحلية والقدرة العرقية",
  ["Trinket for healers only"] = "الحلية للمعالجين فقط",
  ["Turn off Blizzard's combat notifications"] = "إيقاف إشعارات القتال من Blizzard",
  ["Turn off Blizzard's incoming combat text"] = "إيقاف نص القتال الوارد من Blizzard",
  ["Turn off Blizzard's outgoing combat text"] = "إيقاف نص القتال الصادر من Blizzard",
  ["Turn on the client's taint log until logout so blocked actions can be traced."] = "تفعيل سجل التلوث في العميل حتى الخروج لتتبع الإجراءات المحظورة.",
  ["Turns /combatlog on in the content types ticked below and off elsewhere (only a log Flow started). Raids and Mythic+ are ticked to start with."] = "يفعّل الأمر /combatlog في أنواع المحتوى المحددة أدناه ويوقفه في غيرها (فقط سجل بدأه Flow). الغارات والأسطوري+ محددة في البداية.",
  ["Turns :name: codes such as :star: or :tank: into icons, with suggestions while you type."] = "يحوّل رموز :name: مثل :star: أو :tank: إلى أيقونات، مع اقتراحات أثناء الكتابة.",
  ["Turns off the game's tutorial pop-ups; your setting comes back when this is off."] = "يوقف النوافذ التعليمية المنبثقة في اللعبة؛ يعود إعدادك عند إيقاف هذا.",
  ["Turns on the game's own enemy DR tracking (setting spellDiminishPVPEnemiesEnabled) and shows it in Phoenix's tray. Off: no DR is shown. Your old value comes back when this goes off."] = "يفعّل تتبع تناقص المفعول للأعداء الخاص باللعبة (الإعداد spellDiminishPVPEnemiesEnabled) ويعرضه في صينية Phoenix. الإيقاف: لا يُعرض تناقص المفعول. تعود قيمتك القديمة عند إيقاف هذا.",
  ["Turns the Phoenix filter for this category on or off without losing your chips."] = "يفعّل مرشح Phoenix لهذه الفئة أو يوقفه دون فقدان رقائقك.",
  ["Turns the game's friendly nameplates on or off for you. Your own value comes back when Phoenix nameplates turn off."] = "يفعّل لوحات الأسماء الصديقة في اللعبة أو يوقفها لك. تعود قيمتك الخاصة عند إيقاف لوحات أسماء Phoenix.",
  ["Type /keys to list your key, your alts' keys and your group's keys (/pui keys always works)."] = "اكتب /keys لسرد مفتاحك ومفاتيح شخصياتك البديلة ومفاتيح مجموعتك (/pui keys يعمل دائمًا).",
  ["Types the confirmation word when deleting a good item."] = "يكتب كلمة التأكيد عند حذف غرض جيد.",
  ["Typing : and a few letters shows matching emoji; click one or press Tab to insert it."] = "كتابة : وبضعة أحرف تعرض الوجوه التعبيرية المطابقة؛ انقر واحدًا أو اضغط Tab لإدراجه.",
  ["Typing in the add-friend box lists matching guild members and recent players; click one to fill the box."] = "الكتابة في مربع إضافة صديق تسرد أعضاء النقابة واللاعبين الأخيرين المطابقين؛ انقر واحدًا لملء المربع.",
  ["UI errors"] = "أخطاء الواجهة",
  ["Uninterruptible colour"] = "لون غير القابل للمقاطعة",
  ["Uninterruptible colour of plate cast bars."] = "لون غير القابل للمقاطعة لأشرطة إلقاء اللوحات.",
  ["Unit frames"] = "إطارات الوحدات",
  ["Unlocked glow"] = "توهج الفتح",
  ["Unread badges"] = "شارات غير المقروء",
  ["Unusable colour"] = "لون غير القابل للاستخدام",
  ["Upgradable gear shows how many ranks are left and about how many crests they cost."] = "المعدات القابلة للترقية تعرض عدد الرتب المتبقية وكم شعارًا تكلف تقريبًا.",
  ["Upgrade hint"] = "تلميح الترقية",
  ["Upgrade star"] = "نجمة الترقية",
  ["Upgrade track"] = "مسار الترقية",
  ["Use my class colours"] = "استخدام ألوان فئاتي",
  ["Use one font in every Phoenix module, or keep each module's own font choice."] = "استخدام خط واحد في كل وحدات Phoenix، أو إبقاء اختيار الخط لكل وحدة.",
  ["Use the profile you picked for raid, Mythic+, arena and other content automatically. Applies when you enter, never in combat."] = "استخدام الملف الشخصي الذي اخترته للغارة والأسطوري+ والساحة وغيرها من المحتوى تلقائيًا. يُطبّق عند الدخول، وأبدًا أثناء القتال.",
  ["Used when Colour by debuff type is off."] = "يُستخدم عند إيقاف التلوين حسب نوع الضعف.",
  ["Used when Group health colour is Custom."] = "يُستخدم عندما يكون لون صحة المجموعة مخصصًا.",
  ["Used when Health colour is Custom."] = "يُستخدم عندما يكون لون الصحة مخصصًا.",
  ["Uses the Party, Raid up to 10, Raid up to 20 or Raid up to 40 layout automatically as people join and leave. Turn off to always use one raid layout."] = "يستخدم تخطيط المجموعة أو الغارة حتى 10 أو حتى 20 أو حتى 40 تلقائيًا مع انضمام الأشخاص ومغادرتهم. أوقفه لاستخدام تخطيط غارة واحد دائمًا.",
  ["Utility cooldowns"] = "فترات التهدئة المساعدة",
  ["Utility cooldowns: Phoenix layout"] = "فترات التهدئة المساعدة: تخطيط Phoenix",
  ["Utility cooldowns: growth"] = "فترات التهدئة المساعدة: النمو",
  ["Utility cooldowns: icon size"] = "فترات التهدئة المساعدة: حجم الأيقونة",
  ["Utility cooldowns: per row"] = "فترات التهدئة المساعدة: في كل صف",
  ["Utility cooldowns: spacing"] = "فترات التهدئة المساعدة: التباعد",
  ["Vault"] = "Vault",
  ["Vehicle exit"] = "الخروج من المركبة",
  ["Vehicle exit button"] = "زر الخروج من المركبة",
  ["Vehicle exit button button size"] = "حجم زر الخروج من المركبة",
  ["Vehicle exit button fade opacity"] = "عتامة تلاشي زر الخروج من المركبة",
  ["Vehicle exit button fade until mouse-over"] = "تلاشي زر الخروج من المركبة حتى التمرير",
  ["Vehicle seats"] = "مقاعد المركبة",
  ["Vertical distance from the cursor for the left/right cursor positions."] = "المسافة العمودية من المؤشر لمواضع يسار/يمين المؤشر.",
  ["Vertical spacing when stacked"] = "التباعد العمودي عند التكديس",
  ["View"] = "العرض",
  ["Viewer layout"] = "تخطيط العارض",
  ["Viewer opens on"] = "يفتح العارض على",
  ["Viewer shows"] = "يعرض العارض",
  ["Voice deafen button"] = "زر كتم سماع الصوت",
  ["Voice mute button"] = "زر كتم الميكروفون",
  ["Warlock colour"] = "لون المشعوذ",
  ["Warn at (seconds left)"] = "التحذير عند (الثواني المتبقية)",
  ["Warn once on many new errors"] = "التحذير مرة واحدة عند كثرة الأخطاء الجديدة",
  ["Warning level for the low durability warning."] = "مستوى التحذير لتحذير انخفاض المتانة.",
  ["Warns once when any item drops to the threshold."] = "يحذّر مرة واحدة عندما تنخفض متانة أي غرض إلى العتبة.",
  ["Warrior colour"] = "لون المحارب",
  ["Waypoint line"] = "خط نقطة الطريق",
  ["Waypoints (/way): when another addon does this"] = "نقاط الطريق (/way): عندما يقوم ملحق آخر بذلك",
  ["WeakAuras options"] = "خيارات WeakAuras",
  ["Weapon enchants"] = "سحر الأسلحة",
  ["Weapon oil in instances"] = "زيت الأسلحة في المثيلات",
  ["Web addresses in chat become links; click one to copy it."] = "عناوين الويب في الدردشة تصبح روابط؛ انقر واحدًا لنسخه.",
  ["Weekly record, conquest and Great Vault"] = "السجل الأسبوعي والغزو والخزنة العظمى",
  ["What /gg says."] = "ما يقوله الأمر /gg.",
  ["What a left click on a quest does. Right-click opens details, Ctrl-click copies a Wowhead link, Alt-click stops tracking."] = "ما يفعله النقر الأيسر على مهمة. النقر الأيمن يفتح التفاصيل، وCtrl+نقر ينسخ رابط Wowhead، وAlt+نقر يوقف التتبع.",
  ["What a middle click on the minimap opens. The micro menu lists Character, Spellbook, Talents, Collections, Group Finder and more."] = "ما يفتحه النقر الأوسط على الخريطة المصغرة. القائمة المصغرة تضم الشخصية وكتاب التعاويذ والمواهب والمجموعات وأداة البحث عن مجموعة والمزيد.",
  ["What dragged elements snap to while Snap is on: the grid, other elements' edges and centres, or both."] = "ما تلتقط إليه العناصر المسحوبة أثناء تفعيل الالتقاط: الشبكة، أو حواف العناصر الأخرى ومراكزها، أو كلاهما.",
  ["What each party member is targeting, as small frames beside the party."] = "ما يستهدفه كل عضو في المجموعة، كإطارات صغيرة بجوار المجموعة.",
  ["What the DR tray attaches to. Move it further with the offsets."] = "ما تُلحق به صينية تناقص المفعول. حرّكها أكثر بالإزاحات.",
  ["What the center text zone shows."] = "ما تعرضه منطقة النص الوسطى.",
  ["What the left text zone shows."] = "ما تعرضه منطقة النص اليسرى.",
  ["What the power text zone shows."] = "ما تعرضه منطقة نص الطاقة.",
  ["What the right text zone shows."] = "ما تعرضه منطقة النص اليمنى.",
  ["What to announce, by content"] = "ما يُعلن عنه، حسب المحتوى",
  ["What window 1 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "ما تعرضه النافذة 1. التهديد يسرد تهديد مجموعتك على هدفك. يمكنك أيضًا النقر الأيسر على عنوان النافذة للتبديل.",
  ["What window 2 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "ما تعرضه النافذة 2. التهديد يسرد تهديد مجموعتك على هدفك. يمكنك أيضًا النقر الأيسر على عنوان النافذة للتبديل.",
  ["What window 3 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "ما تعرضه النافذة 3. التهديد يسرد تهديد مجموعتك على هدفك. يمكنك أيضًا النقر الأيسر على عنوان النافذة للتبديل.",
  ["What window 4 shows. Threat lists your group's threat on your target. You can also left-click the window title to switch."] = "ما تعرضه النافذة 4. التهديد يسرد تهديد مجموعتك على هدفك. يمكنك أيضًا النقر الأيسر على عنوان النافذة للتبديل.",
  ["What you see when a key finishes: a summary card with time, score change and everyone's numbers, a chat line, or nothing."] = "ما تراه عند انتهاء مفتاح: بطاقة ملخص بالوقت وتغير النقاط وأرقام الجميع، أو سطر دردشة، أو لا شيء.",
  ["When !KalielsTracker, KalielsTracker is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل !KalielsTracker, KalielsTracker، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When AutoQueue is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "عند تحميل AutoQueue، اختر ما إذا كان Phoenix يفعل هذا أيضًا. لا يُعطَّل أي ملحق.",
  ["When Baganator, Bagnon, AdiBags, ArkInventory, BetterBags, Combuctor, LiteBag is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل Baganator, Bagnon, AdiBags, ArkInventory, BetterBags, Combuctor, LiteBag، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When Bartender4, Dominos, ElvUI, EllesmereUIActionBars, ConsolePort_Bar, LUI is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل Bartender4, Dominos, ElvUI, EllesmereUIActionBars, ConsolePort_Bar, LUI، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When BigWigs is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "عند تحميل BigWigs، اختر ما إذا كان Phoenix يفعل هذا أيضًا. لا يُعطَّل أي ملحق.",
  ["When BigWigs, DBM-Core is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "عند تحميل BigWigs, DBM-Core، اختر ما إذا كان Phoenix يفعل هذا أيضًا. لا يُعطَّل أي ملحق.",
  ["When BugSack is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "عند تحميل BugSack، اختر ما إذا كان Phoenix يفعل هذا أيضًا. لا يُعطَّل أي ملحق.",
  ["When Details, Skada, Recount is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل Details, Skada, Recount، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When EllesmereUICooldownManager, BetterCooldownManager, CooldownManagerCentered is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل EllesmereUICooldownManager, BetterCooldownManager, CooldownManagerCentered، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When EllesmereUIResourceBars, SenseiClassResourceBar, PersonalResourceReskin is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل EllesmereUIResourceBars, SenseiClassResourceBar, PersonalResourceReskin، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When MikScrollingBattleText, Parrot, xCT+ is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل MikScrollingBattleText, Parrot, xCT+، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When MythicDungeonTools is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "عند تحميل MythicDungeonTools، اختر ما إذا كان Phoenix يفعل هذا أيضًا. لا يُعطَّل أي ملحق.",
  ["When Prat-3.0, Chattynator, Chatter, Glass, WIM, BasicChatMods is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل Prat-3.0, Chattynator, Chatter, Glass, WIM, BasicChatMods، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When PremadeGroupsFilter is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل PremadeGroupsFilter، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When Questie is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "عند تحميل Questie، اختر ما إذا كان Phoenix يفعل هذا أيضًا. لا يُعطَّل أي ملحق.",
  ["When Studio shows each mover's name."] = "متى يعرض Studio اسم كل محرّك.",
  ["When TomTom is loaded, choose whether Phoenix also does this. Neither addon is turned off."] = "عند تحميل TomTom، اختر ما إذا كان Phoenix يفعل هذا أيضًا. لا يُعطَّل أي ملحق.",
  ["When Unit Frames attaches these bars under your player frame, they take its width. Off keeps the width set here."] = "عندما تُلحق إطارات الوحدات هذه الأشرطة تحت إطار اللاعب، تأخذ عرضه. الإيقاف يبقي العرض المضبوط هنا.",
  ["When WarpDeplete, MythicPlusTimer, AngryKeystones is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل WarpDeplete, MythicPlusTimer, AngryKeystones، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When a battleground ends, a countdown leaves for you. Cancel it or leave at once. Arenas are never left for you."] = "عند انتهاء ساحة معركة، يبدأ عد تنازلي لمغادرتك. ألغه أو غادر فورًا. لا تُغادر الساحات نيابة عنك أبدًا.",
  ["When a cast fails because the target is out of line of sight, its plate flashes with an 'Out of sight' tag (the game has no live line-of-sight check for addons)."] = "عندما يفشل إلقاء لأن الهدف خارج خط الرؤية، تومض لوحته بوسم «خارج الرؤية» (لا تملك اللعبة فحصًا مباشرًا لخط الرؤية للملحقات).",
  ["When a dungeon, raid or battleground invite pops, a countdown shows by the queue eye. Group Finder owns the timer; the minimap only shows it."] = "عند ظهور دعوة زنزانة أو غارة أو ساحة معركة، يظهر عد تنازلي بجوار عين الطابور. المؤقت تملكه أداة البحث عن مجموعة؛ الخريطة المصغرة تعرضه فقط.",
  ["When a tracked cooldown glows."] = "عندما تتوهج فترة تهدئة متتبعة.",
  ["When an NPC colour meets threat"] = "عندما يلتقي لون الشخصية غير اللاعبة بالتهديد",
  ["When an invite pops, a large Enter button appears. Phoenix never presses it for you."] = "عند ظهور دعوة، يظهر زر دخول كبير. لا يضغطه Phoenix نيابة عنك أبدًا.",
  ["When another player sends you a report, you get a prompt first (or it is refused)."] = "عندما يرسل لك لاعب آخر تقريرًا، تتلقى سؤالًا أولًا (أو يُرفض).",
  ["When cast history strips are shown."] = "متى تُعرض أشرطة سجل الإلقاء.",
  ["When casts come faster than the strip moves, it speeds up this much."] = "عندما تأتي الإلقاءات أسرع من حركة الشريط، يتسارع بهذا القدر.",
  ["When sArena, sArena_Reloaded, sArenaReloaded, Gladius, GladiusEx is loaded, choose whether Phoenix or that addon keeps the job. Phoenix keeps it: the other addon is turned off from the next load. The other addon keeps it: this Phoenix module stays off."] = "عند تحميل sArena, sArena_Reloaded, sArenaReloaded, Gladius, GladiusEx، اختر من يتولى المهمة: Phoenix أو ذلك الملحق. إن تولاها Phoenix: يُعطَّل الملحق الآخر من التحميل التالي. إن تولاها الملحق الآخر: تبقى وحدة Phoenix هذه متوقفة.",
  ["When someone types !keys in party chat, your key is posted through Phoenix announcements (Keystones topic decides where)."] = "عندما يكتب أحدهم !keys في دردشة المجموعة، يُنشر مفتاحك عبر إعلانات Phoenix (موضوع المفاتيح يحدد الوجهة).",
  ["When the combat timer is shown."] = "متى يُعرض مؤقت القتال.",
  ["When the global cooldown bar is drawn."] = "متى يُرسم شريط فترة التهدئة العامة.",
  ["When the language uses letters the game font lacks (Arabic, or Russian and Chinese on another client), Phoenix text uses a matching font from the media pack."] = "عندما تستخدم اللغة حروفًا يفتقدها خط اللعبة (العربية، أو الروسية والصينية على عميل آخر)، يستخدم نص Phoenix خطًا مطابقًا من حزمة الوسائط.",
  ["When the warning sound plays."] = "متى يُشغّل صوت التحذير.",
  ["When too many lines come at once, the extra ones are counted and shown as one \"+N more\" line."] = "عندما تأتي أسطر كثيرة دفعة واحدة، تُعدّ الزائدة وتُعرض كسطر واحد «+N أخرى».",
  ["When tooltips are hidden in combat, holding this key shows them anyway."] = "عندما تكون التلميحات مخفية أثناء القتال، الضغط مطولًا على هذا المفتاح يعرضها رغم ذلك.",
  ["When you are below the last visible row, your own row replaces it with your real rank."] = "عندما تكون تحت آخر صف ظاهر، يحل صفك محله برتبتك الحقيقية.",
  ["When your group is ready or a Group Finder group invites you, the game icon flashes, a sound plays and a notice appears."] = "عندما تكون مجموعتك جاهزة أو تدعوك مجموعة من أداة البحث عن مجموعة، تومض أيقونة اللعبة ويُشغّل صوت ويظهر إشعار.",
  ["Where Mythic+ score colours come from in tooltips, Group Finder and data bars."] = "مصدر ألوان نقاط الأسطوري+ في التلميحات وأداة البحث عن مجموعة وأشرطة البيانات.",
  ["Where announcements go. Only me prints a local line nobody else sees; Group picks party, raid or instance for you."] = "وجهة الإعلانات. «أنا فقط» يطبع سطرًا محليًا لا يراه أحد غيرك؛ «المجموعة» تختار المجموعة أو الغارة أو المثيل لك.",
  ["Where auto combat logging turns the log on. Works alongside recorder addons: a log they started is never stopped."] = "أين يفعّل التسجيل التلقائي للقتال السجل. يعمل مع ملحقات التسجيل: السجل الذي بدأته لا يُوقف أبدًا.",
  ["Where each online friend is."] = "أين يوجد كل صديق متصل.",
  ["Where each pet frame sits."] = "أين يقع كل إطار رفيق.",
  ["Where on the frame the private auras sit."] = "أين تقع التأثيرات الخاصة على الإطار.",
  ["Where text lines up in the area."] = "محاذاة النص في المنطقة.",
  ["Where the M+ block sits"] = "أين تقع كتلة الأسطوري+",
  ["Where the Phoenix panel sits next to the group finder."] = "أين تقع لوحة Phoenix بجوار أداة البحث عن مجموعة.",
  ["Where the channel bar sits next to chat window 1."] = "أين يقع شريط القنوات بجوار نافذة الدردشة 1.",
  ["Where the clock sits on the minimap."] = "أين تقع الساعة على الخريطة المصغرة.",
  ["Where the coordinates sit."] = "أين تقع الإحداثيات.",
  ["Where the detached panel sits."] = "أين تقع اللوحة المنفصلة.",
  ["Where the difficulty text sits."] = "أين يقع نص الصعوبة.",
  ["Where the dispel icons sit."] = "أين تقع أيقونات التبديد.",
  ["Where the elite / rare icon sits on enemy plates. You can also drag it in the preview."] = "أين تقع أيقونة النخبة / النادر على لوحات الأعداء. يمكنك أيضًا سحبها في المعاينة.",
  ["Where the game blocks addon chat (Mythic+, PvP, boss fights), a report waits and posts when the key, match or boss ends. Say and Yell ask you first."] = "حيث تحظر اللعبة دردشة الملحقات (الأسطوري+، PvP، معارك الزعماء)، ينتظر التقرير ويُنشر عند انتهاء المفتاح أو المباراة أو الزعيم. القول والصراخ يسألانك أولًا.",
  ["Where the game's DR data is drawn. Needs DR tracking on."] = "أين تُرسم بيانات تناقص المفعول من اللعبة. يحتاج تفعيل تتبع تناقص المفعول.",
  ["Where the health text sits on enemy plates. You can also drag it in the preview."] = "أين يقع نص الصحة على لوحات الأعداء. يمكنك أيضًا سحبه في المعاينة.",
  ["Where the health text sits."] = "أين يقع نص الصحة.",
  ["Where the m+ forces sits on enemy plates. You can also drag it in the preview."] = "أين تقع قوات الأسطوري+ على لوحات الأعداء. يمكنك أيضًا سحبها في المعاينة.",
  ["Where the name sits on enemy plates. You can also drag it in the preview."] = "أين يقع الاسم على لوحات الأعداء. يمكنك أيضًا سحبه في المعاينة.",
  ["Where the name sits on the frame."] = "أين يقع الاسم على الإطار.",
  ["Where the name sits on the health bar."] = "أين يقع الاسم على شريط الصحة.",
  ["Where the power bar sits."] = "أين يقع شريط الطاقة.",
  ["Where the quest icon sits on enemy plates. You can also drag it in the preview."] = "أين تقع أيقونة المهمة على لوحات الأعداء. يمكنك أيضًا سحبها في المعاينة.",
  ["Where the raid marker sits on enemy plates. You can also drag it in the preview."] = "أين تقع علامة الغارة على لوحات الأعداء. يمكنك أيضًا سحبها في المعاينة.",
  ["Where the search panel sits."] = "أين تقع لوحة البحث.",
  ["Where the window opens on screen. Dragging the window updates this."] = "أين تُفتح النافذة على الشاشة. سحب النافذة يحدّث هذا.",
  ["Where the zone name sits on the minimap."] = "أين يقع اسم المنطقة على الخريطة المصغرة.",
  ["Where to remind"] = "أين يُذكَّر",
  ["Where to show"] = "أين يظهر",
  ["Where to switch"] = "أين يُبدَّل",
  ["Which action page (12 slots) bar 10 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 10.",
  ["Which action page (12 slots) bar 2 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 2.",
  ["Which action page (12 slots) bar 3 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 3.",
  ["Which action page (12 slots) bar 4 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 4.",
  ["Which action page (12 slots) bar 5 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 5.",
  ["Which action page (12 slots) bar 6 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 6.",
  ["Which action page (12 slots) bar 7 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 7.",
  ["Which action page (12 slots) bar 8 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 8.",
  ["Which action page (12 slots) bar 9 shows."] = "أي صفحة أوامر (12 خانة) يعرضها الشريط 9.",
  ["Which auras are shown."] = "أي التأثيرات تُعرض.",
  ["Which auras this lane shows."] = "أي التأثيرات يعرضها هذا المسار.",
  ["Which battlegrounds use the countdown."] = "أي ساحات المعارك تستخدم العد التنازلي.",
  ["Which buffs are shown."] = "أي التعزيزات تُعرض.",
  ["Which colour a listed NPC gets in combat."] = "أي لون تأخذه الشخصية غير اللاعبة المدرجة أثناء القتال.",
  ["Which corner of the conquest frame the panel sits in."] = "في أي زاوية من إطار الغزو تقع اللوحة.",
  ["Which debuffs are shown."] = "أي الضعف يُعرض.",
  ["Which errors the viewer lists first."] = "الأخطاء التي يسردها العارض أولًا.",
  ["Which minimap corner the Phoenix buttons start from."] = "زاوية الخريطة المصغرة التي تبدأ منها أزرار Phoenix.",
  ["Which of your runs boss splits are compared with."] = "أي من جولاتك تُقارن بها تقسيمات الزعماء.",
  ["Which scroll area shows it."] = "منطقة التمرير التي تعرضه.",
  ["Which session the viewer shows first."] = "الجلسة التي يعرضها العارض أولًا.",
  ["Which side of the bar the icon sits on."] = "جانب الشريط الذي تقع عليه الأيقونة.",
  ["Which side of the cast bar the icon sits on."] = "جانب شريط الإلقاء الذي تقع عليه الأيقونة.",
  ["Which side of the frame the portrait sits on."] = "جانب الإطار الذي تقع عليه الصورة.",
  ["Which side the spec icon sits on."] = "الجانب الذي تقع عليه أيقونة التخصص.",
  ["Which sound plays: four game sounds, then every sound in the media library (yours and other addons' shared sounds)."] = "الصوت الذي يُشغّل: أربعة أصوات من اللعبة، ثم كل صوت في مكتبة الوسائط (أصواتك والأصوات المشتركة من الملحقات الأخرى).",
  ["Which tiers the pace line compares against."] = "المستويات التي يقارن بها خط الوتيرة.",
  ["Which way boss frames 2 to 5 are added."] = "اتجاه إضافة إطارات الزعماء 2 إلى 5.",
  ["Which way buttons fill a line; the popup opens and the bar docks on that side."] = "اتجاه ملء الأزرار للسطر؛ تُفتح النافذة المنبثقة ويرسو الشريط على ذلك الجانب.",
  ["Which way extra rows are added."] = "اتجاه إضافة الصفوف الإضافية.",
  ["Which way extra rows of bar 1 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 1.",
  ["Which way extra rows of bar 10 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 10.",
  ["Which way extra rows of bar 2 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 2.",
  ["Which way extra rows of bar 3 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 3.",
  ["Which way extra rows of bar 4 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 4.",
  ["Which way extra rows of bar 5 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 5.",
  ["Which way extra rows of bar 6 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 6.",
  ["Which way extra rows of bar 7 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 7.",
  ["Which way extra rows of bar 8 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 8.",
  ["Which way extra rows of bar 9 are added."] = "اتجاه إضافة الصفوف الإضافية للشريط 9.",
  ["Which way lines scroll."] = "اتجاه تمرير الأسطر.",
  ["Which way new icons are added on a row."] = "اتجاه إضافة الأيقونات الجديدة في الصف.",
  ["Which way older casts move."] = "اتجاه حركة الإلقاءات الأقدم.",
  ["Which way the buttons of bar 1 run."] = "اتجاه أزرار الشريط 1.",
  ["Which way the buttons of bar 10 run."] = "اتجاه أزرار الشريط 10.",
  ["Which way the buttons of bar 2 run."] = "اتجاه أزرار الشريط 2.",
  ["Which way the buttons of bar 3 run."] = "اتجاه أزرار الشريط 3.",
  ["Which way the buttons of bar 4 run."] = "اتجاه أزرار الشريط 4.",
  ["Which way the buttons of bar 5 run."] = "اتجاه أزرار الشريط 5.",
  ["Which way the buttons of bar 6 run."] = "اتجاه أزرار الشريط 6.",
  ["Which way the buttons of bar 7 run."] = "اتجاه أزرار الشريط 7.",
  ["Which way the buttons of bar 8 run."] = "اتجاه أزرار الشريط 8.",
  ["Which way the buttons of bar 9 run."] = "اتجاه أزرار الشريط 9.",
  ["While Pulse shows boss bars, sets the game's own timeline to its empty view. Your previous view comes back when you turn this off."] = "أثناء عرض Pulse لأشرطة الزعماء، يضبط الخط الزمني الخاص باللعبة على العرض الفارغ. يعود عرضك السابق عند إيقاف هذا.",
  ["While Spark is on, the game's combat state, reactive, honor and reputation popups are off. Restored when this or Spark is off."] = "أثناء تفعيل Spark، تُوقف نوافذ اللعبة المنبثقة لحالة القتال وردود الفعل والشرف والسمعة. تُستعاد عند إيقاف هذا أو Spark.",
  ["While Spark is on, the game's own damage and healing numbers over enemies are off. Your old setting comes back when this or Spark is off."] = "أثناء تفعيل Spark، تُوقف أرقام الضرر والشفاء الخاصة باللعبة فوق الأعداء. يعود إعدادك القديم عند إيقاف هذا أو Spark.",
  ["While Spark is on, the game's own text over your character is off. Restored when this or Spark is off."] = "أثناء تفعيل Spark، يُوقف نص اللعبة فوق شخصيتك. يُستعاد عند إيقاف هذا أو Spark.",
  ["While a key runs, Ascent's Mythic+ block sits at the top of the tracker (Ascent owns the timer)."] = "أثناء جريان مفتاح، تقع كتلة الأسطوري+ من Ascent أعلى المتتبع (المؤقت يملكه Ascent).",
  ["While a report waits, it also opens in the copy box so you can paste it yourself."] = "أثناء انتظار تقرير، يُفتح أيضًا في مربع النسخ لتلصقه بنفسك.",
  ["While a tooltip shows IDs, this key opens them in the copy box. It is only taken while IDs are on screen, and never over a key you bound yourself. Empty turns it off."] = "أثناء عرض تلميح للمعرّفات، يفتحها هذا المفتاح في مربع النسخ. لا يُؤخذ إلا أثناء ظهور المعرّفات على الشاشة، وأبدًا فوق مفتاح ربطته بنفسك. الفارغ يوقفه.",
  ["While an achievement ID setting is 0, Phoenix looks up the season's title achievement in the game's list (once per season) and reads its progress."] = "أثناء كون إعداد معرّف الإنجاز 0، يبحث Phoenix عن إنجاز لقب الموسم في قائمة اللعبة (مرة في كل موسم) ويقرأ تقدمه.",
  ["While the developer profiler has samples, each module page shows how much time that module took."] = "أثناء وجود عينات لدى محلل أداء المطور، تعرض كل صفحة وحدة كم من الوقت استغرقت تلك الوحدة.",
  ["While you fish: a bar with the time left on the cast and a catch counter for this session. Off by default."] = "أثناء الصيد: شريط بالوقت المتبقي للرمية وعدّاد للصيد في هذه الجلسة. متوقف افتراضيًا.",
  ["Whisper sound"] = "صوت الهمس",
  ["Whisper tab width"] = "عرض تبويب الهمس",
  ["Whisper window width"] = "عرض نافذة الهمس",
  ["Who shows coordinates"] = "من يعرض الإحداثيات",
  ["Who the player is targeting."] = "من يستهدفه اللاعب.",
  ["Whose auras the sounds watch: you (boss debuffs on you), your target or your focus."] = "تأثيرات من تراقبها الأصوات: أنت (ضعف الزعماء عليك)، أو هدفك، أو تركيزك.",
  ["Widget power bar"] = "شريط طاقة الأداة",
  ["Widgets and alt power"] = "الأدوات والطاقة البديلة",
  ["Widgets below the minimap"] = "الأدوات تحت الخريطة المصغرة",
