  ["Width of the focus frame in pixels."] = "عرض إطار التركيز بالبكسل.",
  ["Width of the focus target frame in pixels."] = "عرض إطار هدف التركيز بالبكسل.",
  ["Width of the personal resource bar stack."] = "عرض كومة أشرطة الموارد الشخصية.",
