  ["Window animations"] = "حركات النوافذ",
  ["Window background opacity."] = "عتامة خلفية النافذة.",
  ["Window border"] = "حد النافذة",
  ["Window drag strip height"] = "ارتفاع شريط سحب النافذة",
  ["Window gear button"] = "زر ترس النافذة",
  ["Window layout"] = "تخطيط النافذة",
