  ["Window snapping"] = "التقاط النوافذ",
  ["Window text outline"] = "حد نص النافذة",
  ["Window tint"] = "صبغة النافذة",
  ["Window width"] = "عرض النافذة",
  ["Windows 2-4 dock to the previous one, so moving window 1 moves the set."] = "النوافذ 2-4 ترسو على السابقة، فتحريك النافذة 1 يحرّك المجموعة.",
  ["Windows open where you last left them. Off: they move only until closed."] = "تُفتح النوافذ حيث تركتها آخر مرة. الإيقاف: تتحرك فقط حتى تُغلق.",
  ["Wins needed when Phoenix counts them itself."] = "الانتصارات اللازمة عندما يعدّها Phoenix بنفسه.",
  ["Wins toward each title. Uses the game's own achievement count when the season has one; otherwise Phoenix counts wins taken at or above the title rating."] = "الانتصارات نحو كل لقب. يستخدم عدّاد إنجاز اللعبة عندما يكون للموسم واحد؛ وإلا يعدّ Phoenix الانتصارات المحققة عند تصنيف اللقب أو أعلى.",
  ["Wisdom"] = "الحكمة",
  ["With BigWigs loaded, adds a \"Phoenix UI\" bar style you can pick in BigWigs' bar options."] = "مع تحميل BigWigs، يضيف نمط أشرطة «Phoenix UI» يمكنك اختياره في خيارات أشرطة BigWigs.",
  ["With FrameSort loaded, the arena numbers follow its sorted enemy order (matching its EnemyFrame macros)."] = "مع تحميل FrameSort، تتبع أرقام الساحة ترتيب الأعداء المفرز لديه (مطابقة لماكرو EnemyFrame الخاص به).",
  ["With In game only, also leave out friends playing a different version of World of Warcraft."] = "مع «داخل اللعبة فقط»، يُستبعد أيضًا الأصدقاء الذين يلعبون إصدارًا مختلفًا من World of Warcraft.",
  ["With Masque loaded, cast icons use the skin you pick for \"Phoenix UI: Cast History\" in Masque."] = "مع تحميل Masque، تستخدم أيقونات الإلقاء المظهر الذي تختاره لـ «Phoenix UI: Cast History» في Masque.",
  ["With Raider.IO loaded, adds the leader's Raider.IO score to each row (filter words rio and riomain work either way)."] = "مع تحميل Raider.IO، يضيف نقاط Raider.IO للقائد إلى كل صف (كلمتا المرشح rio وriomain تعملان في الحالتين).",
  ["With several elements selected, dragging one moves them all."] = "مع تحديد عدة عناصر، سحب أحدها يحرّكها كلها.",
  ["Words for the dungeons, raids or delves to keep (see the word list in the help panel; the season's words are added live). Empty keeps all."] = "كلمات الزنزانات أو الغارات أو الأغوار التي تُبقى (انظر قائمة الكلمات في لوحة المساعدة؛ كلمات الموسم تُضاف مباشرة). الفارغ يبقي الكل.",
  ["Words never hidden in paths"] = "كلمات لا تُخفى أبدًا في المسارات",
  ["World label colour"] = "لون تسمية العالم",
  ["World loot list"] = "قائمة غنائم العالم",
  ["World markers"] = "علامات العالم",
  ["World: Achievement ID"] = "العالم: معرّف الإنجاز",
  ["World: Area POI ID"] = "العالم: معرّف نقطة اهتمام المنطقة",
  ["World: Criteria ID"] = "العالم: معرّف المعيار",
  ["World: Currency ID"] = "العالم: معرّف العملة",
  ["World: NPC ID"] = "العالم: معرّف الشخصية غير اللاعبة",
  ["World: Object ID"] = "العالم: معرّف الكائن",
  ["World: Quest ID"] = "العالم: معرّف المهمة",
  ["World: Vignette ID"] = "العالم: معرّف المعلم",
  ["Write every readable number in thousands, millions or billions."] = "كتابة كل رقم مقروء بالآلاف أو الملايين أو المليارات.",
  ["Writes 1, 2, 3 beside each frame (matches /target arena1)."] = "يكتب 1 و2 و3 بجوار كل إطار (يطابق /target arena1).",
  ["Writes 1., 2., 3. before names."] = "يكتب 1. و2. و3. قبل الأسماء.",
  ["Writes 1/2, 1/4 or immune when the game's values are readable (hidden values show icon and swipe only)."] = "يكتب 1/2 أو 1/4 أو محصّن عندما تكون قيم اللعبة مقروءة (القيم المخفية تعرض الأيقونة والمسحة فقط).",
  ["Writes Blizzard's own server-side minimum rating filter. Your previous Blizzard filter is saved and put back when this returns to 0."] = "يكتب مرشح الحد الأدنى للتصنيف الخاص بخادم Blizzard. يُحفظ مرشح Blizzard السابق ويُعاد عندما يعود هذا إلى 0.",
  ["Writes W or L for each round once the game shows the round count plainly (it is hidden during play)."] = "يكتب W أو L لكل جولة بمجرد أن تعرض اللعبة عدد الجولات بوضوح (يكون مخفيًا أثناء اللعب).",
  ["Writes the boss name (or Combat) before the time."] = "يكتب اسم الزعيم (أو القتال) قبل الوقت.",
  ["Writes the buff name under each icon."] = "يكتب اسم التعزيز تحت كل أيقونة.",
  ["Writes the item level on equippable items."] = "يكتب مستوى الغرض على الأغراض القابلة للتجهيز.",
  ["Writes the pet's name on its bar (the game may hide some)."] = "يكتب اسم الرفيق على شريطه (قد تخفي اللعبة بعضها).",
  ["Writes the quest level before the title."] = "يكتب مستوى المهمة قبل العنوان.",
  ["XP / reputation / honor bar"] = "شريط الخبرة / السمعة / الشرف",
  ["XP / reputation bar"] = "شريط الخبرة / السمعة",
  ["Yellow below (seconds)"] = "أصفر دون (ثوانٍ)",
  ["You and each party member get your own frame that you can move anywhere in Studio, instead of one row. Sorting by role does not apply while this is on."] = "تحصل أنت وكل عضو في المجموعة على إطار خاص يمكنك تحريكه إلى أي مكان في Studio، بدل صف واحد. الفرز حسب الدور لا يُطبّق أثناء التفعيل.",
  ["Your character name is replaced by [player] as a whole word, and GUIDs keep only their kind, before anything is shared or uploaded."] = "يُستبدل اسم شخصيتك بـ [player] ككلمة كاملة، وتحتفظ معرّفات GUID بنوعها فقط، قبل مشاركة أي شيء أو رفعه.",
  ["Your damage"] = "ضررك",
  ["Your damage: area"] = "ضررك: المنطقة",
  ["Your damage: colour"] = "ضررك: اللون",
  ["Your damage: message"] = "ضررك: الرسالة",
  ["Your damage: sound"] = "ضررك: الصوت",
  ["Your debuff timers change colour in the last 30 % of their duration, when refreshing loses nothing."] = "تغيّر مؤقتات ضعفك لونها في آخر 30 % من مدتها، حين لا يخسر التجديد شيئًا.",
  ["Your debuffs"] = "ضعفك",
  ["Your debuffs on the enemy, above the plate."] = "ضعفك على العدو، فوق اللوحة.",
  ["Your debuffs: how many"] = "ضعفك: كم",
  ["Your debuffs: icon size"] = "ضعفك: حجم الأيقونة",
  ["Your debuffs: which ones"] = "ضعفك: أيها",
  ["Your drag order (Edit mode)."] = "ترتيب السحب الخاص بك (وضع التحرير).",
  ["Your focus target's cast bar with your interrupt's cooldown beside it. Move it in Studio."] = "شريط إلقاء هدف تركيزك مع فترة تهدئة مقاطعتك بجواره. حرّكه في Studio.",
  ["Your heals"] = "شفاؤك",
  ["Your heals: area"] = "شفاؤك: المنطقة",
  ["Your heals: colour"] = "شفاؤك: اللون",
  ["Your heals: message"] = "شفاؤك: الرسالة",
  ["Your heals: sound"] = "شفاؤك: الصوت",
  ["Your last rated match and how much it moved your rating."] = "آخر مباراة مصنفة لك ومقدار تحريكها لتصنيفك.",
  ["Your lockout on raid rows"] = "إقفالك على صفوف الغارات",
  ["Your misses"] = "ضرباتك الضائعة",
