  ["Your misses: message"] = "ضرباتك الضائعة: الرسالة",
  ["Your misses: sound"] = "ضرباتك الضائعة: الصوت",
  ["Your note after each friend in the search panel."] = "ملاحظتك بعد كل صديق في لوحة البحث.",
  ["Your own categories, one per line as Name|rule, checked before the built-in ones. Example: Sets: PvP|set ~ PvP and ilvl >= 640. Fields: type, subtype, ilvl, quality, name, id, bound, expansion, slot, count, set, keystone."] = "فئاتك الخاصة، واحدة في كل سطر بصيغة Name|rule، تُفحص قبل الفئات المدمجة. مثال: Sets: PvP|set ~ PvP and ilvl >= 640. الحقول: type، subtype، ilvl، quality، name، id، bound، expansion، slot، count، set، keystone.",
  ["Your own lines for casts, auras and combat. Build them with /pui spark trigger."] = "أسطرك الخاصة للإلقاءات والتأثيرات والقتال. أنشئها بالأمر /pui spark trigger.",
  ["Your own messages never trigger keyword alerts."] = "رسائلك الخاصة لا تطلق تنبيهات الكلمات المفتاحية أبدًا.",
  ["Your row is tinted with the accent colour."] = "يُصبغ صفك بلون التمييز.",
  ["Your team's rows get a light tint."] = "تحصل صفوف فريقك على صبغة خفيفة.",
  ["Your triggers"] = "مشغّلاتك",
