  ["The battle res button shows the group's shared charges and recharge timer (keys and boss fights) instead of the spell's own cooldown."] = "يعرض زر إحياء المعركة الشحنات المشتركة للمجموعة ومؤقت إعادة الشحن (المفاتيح ومعارك الزعماء) بدلًا من فترة تهدئة التعويذة نفسها.",
  ["Tick the categories each auto item bar fills itself with, from your bags and gear. Rows run top to bottom in the order the buttons appear."] = "حدد الفئات التي يملأ بها كل شريط أغراض تلقائي نفسه من حقائبك وعتادك. تسير الصفوف من الأعلى إلى الأسفل بترتيب ظهور الأزرار.",
  ["Turns auto item bar 1 on. It fills itself with the categories ticked for it."] = "يشغّل شريط الأغراض التلقائي 1. يملأ نفسه بالفئات المحددة له.",
